pub fn r_half_regs() -> i64 {
    i64_quotient(register_regs(), 2i64)
}

pub fn r_repeat(mut b: bool, mut n: i64, mut acc: List<bool>) -> List<bool> {
    loop {
        if i64_eq(n, 0i64) {
            return acc;
        } else {
            (n, acc) = (i64_minus(n, 1i64), kayak_rt::heap_cons(b, acc));
            continue;
        }
    }
}

pub fn r_budget(fs: List<bool>, next: i64) -> List<bool> {
    if null_p(fs) {
        nil::<bool>()
    } else if (car(fs) && i64_lt(next, r_half_regs())) {
        kayak_rt::heap_cons(true, r_budget(cdr(fs), i64_plus(next, 1i64)))
    } else {
        kayak_rt::heap_cons(false, r_budget(cdr(fs), next))
    }
}

// Each of `inits`' flags, onto `after`: set where nothing after it calls;
