pub fn r_split(env: Renv, x: &'static Cx) -> &'static Rsplit {
    let c = r_known(env, x);
    let small = if null_p(c) {
        nil::<Int>()
    } else {
        r_const_small(car(c))
    };
    if not(null_p(small)) {
        rsplit(nil::<&'static Cx>(), car(small))
    } else {
        let s = {
            let tagcase_ = x;
            match *tagcase_ {
                Cx::XApp(f, args, a) => {
                    r_split_app(env, r_standard_name(env, f), args)
                }
                _ => {
                    let y = tagcase_;
                    nil::<&'static Rsplit>()
                }
            }
        };
        if null_p(s) {
            rsplit(kayak_rt::heap_cons(x, kayak_rt::nil()), int_lit(0))
        } else {
            car(s)
        }
    }
}

pub fn r_split_app(env: Renv, name: Str, args: Cxs) -> List<&'static Rsplit> {
    if (not(i64_eq(size(args), 2i64)) || not(r_add_name_p(name))) {
        nil::<&'static Rsplit>()
    } else {
        let tagcase_ = r_split(env, car(args));
        match *tagcase_ {
            Rsplit::Rsplit(pa, ka) => {
                let tagcase_ = r_split(env, car(cdr(args)));
                match *tagcase_ {
                    Rsplit::Rsplit(pb, kb) => {
                        let plus = string_eq_p(name, str_lit("+"));
                        let k = if plus {
                            _plus(ka, kb)
                        } else {
                            _minus(ka, kb)
                        };
                        if (plus && not(null_p(pa)) && not(null_p(pb))) {
                            nil::<&'static Rsplit>()
                        } else if (not(plus) && not(null_p(pb))) {
                            nil::<&'static Rsplit>()
                        } else if not(r_small_p(k)) {
                            nil::<&'static Rsplit>()
                        } else {
                            kayak_rt::heap_cons(rsplit(if null_p(pa) {
                                pb
                            } else {
                                pa
                            }, k), kayak_rt::nil())
                        }
                    }
                }
            }
        }
    }
}

pub fn r_adds_p(env: Renv, e: &'static Cx) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Cx::XApp(f, args, a) => {
            (i64_eq(size(args), 2i64) && r_add_name_p(r_standard_name(env, f)))
        }
        _ => {
            let y = tagcase_;
            false
        }
    }
}

pub fn r_same_exp_p(a: &'static Cx, b: &'static Cx) -> bool {
    i64_eq(cx_start(a), cx_start(b))
}

pub fn r_deeper_p(core: Cxs, x: &'static Cx, y: &'static Cx) -> bool {
    (not(null_p(core)) && not(r_same_exp_p(car(core), x)) && not(r_same_exp_p(car(core), y)))
}

pub fn r_free_operand_p(env: Renv, x: &'static Cx) -> bool {
    (r_simple_p(x) || not(null_p(r_known(env, x))))
}

// The operand an identity leaves (`x + 0`, `0 + x`, `x - 0`, `x * 1`,
// `1 * x`), in a list.
pub fn r_identity_arg(env: Renv, name: Str, args: Cxs) -> Cxs {
    if (not(i64_eq(size(args), 2i64)) || not(string_member_p(name, kayak_rt::heap_cons(str_lit("+"), kayak_rt::heap_cons(str_lit("-"), kayak_rt::heap_cons(str_lit("*"), kayak_rt::nil())))))) {
        nil::<&'static Cx>()
    } else {
        let x = car(args);
        let y = car(cdr(args));
        let a = r_known(env, x);
        let b = r_known(env, y);
        let is = lambda2s(move |c: List<&'static Rconst>, n: Int| {
            (not(null_p(c)) && {
                let tagcase_ = car(c);
                match *tagcase_ {
                    Rconst::RcInt(k) => {
                        _eq(k, n)
                    }
                    _ => {
                        let z = tagcase_;
                        false
                    }
                }
            })
        });
        if (string_eq_p(name, str_lit("+")) && is(b, int_lit(0))) {
            kayak_rt::heap_cons(x, kayak_rt::nil())
        } else if (string_eq_p(name, str_lit("+")) && is(a, int_lit(0))) {
            kayak_rt::heap_cons(y, kayak_rt::nil())
        } else if (string_eq_p(name, str_lit("-")) && is(b, int_lit(0))) {
            kayak_rt::heap_cons(x, kayak_rt::nil())
        } else if (string_eq_p(name, str_lit("*")) && is(b, int_lit(1))) {
            kayak_rt::heap_cons(x, kayak_rt::nil())
        } else if (string_eq_p(name, str_lit("*")) && is(a, int_lit(1))) {
            kayak_rt::heap_cons(y, kayak_rt::nil())
        } else {
            nil::<&'static Cx>()
        }
    }
}

pub fn r_plain_var_loc(env: Renv, x: &'static Cx) -> Rlocs {
    r_var_loc(env, x)
}

pub fn r_var_in_reg_p(env: Renv, x: &'static Cx) -> bool {
    i64_gt(r_reg_of(r_plain_var_loc(env, x)), 0i64)
}

// Whether `f` is the procedure running, called with its arity: its own
// name, still bound where the procedure knows itself to be.
pub fn r_self_known_p(g: &'static Rgen, f: &'static Cx, nargs: i64, te: Cenv) -> bool {
    let tagcase_ = f;
    match *tagcase_ {
        Cx::XVar(n, a) => {
            let me = g_this(g);
            (not(null_p(me)) && {
                let tagcase_ = car(me);
                match *tagcase_ {
                    This::This(m, at, k) => {
                        (string_eq_p(m, n) && i64_eq(k, nargs) && {
                            let l = c_find(te, n);
                            (not(null_p(l)) && c_this_loc_p(car(l), at))
                        })
                    }
                }
            })
        }
        _ => {
            let y = tagcase_;
            false
        }
    }
}

// The global `f` names, in a list, when it is the procedure's own, called
// with its arity.
pub fn r_own_self(g: &'static Rgen, env: Renv, f: &'static Cx, args: Cxs) -> Strings {
    let x = g_ctx(g);
    if (string_eq_p(x_own(x), str_lit("")) || i64_lt(x_own_start(x), 0i64) || not(i64_eq(size(args), x_own_arity(x)))) {
        nil::<Str>()
    } else {
        let tagcase_ = f;
        match *tagcase_ {
            Cx::XVar(m, a) => {
                if string_eq_p(m, x_own(x)) {
                    let l = r_var_loc(env, f);
                    if (not(null_p(l)) && {
                        let tagcase_ = car(l);
                        match *tagcase_ {
                            Rloc::RlGlobal(c) => {
                                true
                            }
                            _ => {
                                let y = tagcase_;
                                false
                            }
                        }
                    }) {
                        kayak_rt::heap_cons(m, kayak_rt::nil())
                    } else {
                        nil::<Str>()
                    }
                } else {
                    nil::<Str>()
                }
            }
            _ => {
                let y = tagcase_;
                nil::<Str>()
            }
        }
    }
}

// A call of global `f` taking `k` arguments, inlined (C252): its noted
// body, if `f` names one seen here, not already being inlined, in a list.
pub fn r_inlined(env: Renv, f: &'static Cx, k: i64) -> List<&'static Rinline> {
    let tagcase_ = f;
    match *tagcase_ {
        Cx::XVar(n, a) => {
            if std_marked_p(n) {
                nil::<&'static Rinline>()
            } else {
                let l = r_where(env, n);
                if (null_p(l) || not(null_p(r_local_loc(env, inlining_name(n))))) {
                    nil::<&'static Rinline>()
                } else {
                    let tagcase_ = car(l);
                    match *tagcase_ {
                        Rloc::RlGlobal(c) => {
                            r_inline_named(get(cg_inlines()), n, k, r_genv(env))
                        }
                        _ => {
                            let y = tagcase_;
                            nil::<&'static Rinline>()
                        }
                    }
                }
            }
        }
        _ => {
            let y = tagcase_;
            nil::<&'static Rinline>()
        }
    }
}

// How many bindings of `env` are named `n`.
pub fn r_count_named(mut env: Renv, mut n: Str, mut k: i64) -> i64 {
    loop {
        if null_p(env) {
            return k;
        } else {
            (env, k) = (cdr(env), {
                let tagcase_ = car(env);
                match *tagcase_ {
                    Rbind::Rbind(m, l) => {
                        if string_eq_p(m, n) {
                            i64_plus(k, 1i64)
                        } else {
                            k
                        }
                    }
                }
            });
            continue;
        }
    }
}

// Whether any of `args` is a constant list (`nil`, as kayak knows them).
pub fn r_any_const_list_p(env: Renv, args: Cxs) -> bool {
    (not(null_p(args)) && ({
        let k = r_known(env, car(args));
        (not(null_p(k)) && {
            let tagcase_ = car(k);
            match *tagcase_ {
                Rconst::RcNil() => {
                    true
                }
                _ => {
                    let y = tagcase_;
                    false
                }
            }
        })
    } || r_any_const_list_p(env, cdr(args))))
}

// A call of global `f` on `args` unrolled (C252, Fixpt's `r-unrolled`):
// `f` noted to be unrolled, seen here, not unrolled 16 deep here, called
// with a constant list: its body, in a list.
pub fn r_unrolled(env: Renv, f: &'static Cx, args: Cxs) -> List<&'static Rinline> {
    let tagcase_ = f;
    match *tagcase_ {
        Cx::XVar(n, a) => {
            if std_marked_p(n) {
                nil::<&'static Rinline>()
            } else {
                let l = r_where(env, n);
                if (null_p(l) || not({
                    let tagcase_ = car(l);
                    match *tagcase_ {
                        Rloc::RlGlobal(c) => {
                            true
                        }
                        _ => {
                            let y = tagcase_;
                            false
                        }
                    }
                }) || i64_gt_eq(r_count_named(env, inlining_name(n), 0i64), r_unroll_depth()) || not(r_any_const_list_p(env, args))) {
                    nil::<&'static Rinline>()
                } else {
                    r_inline_named(get(cg_unrolls()), n, size(args), r_genv(env))
                }
            }
        }
        _ => {
            let y = tagcase_;
            nil::<&'static Rinline>()
        }
    }
}

// An inlined body's environment: its parameters, `params`; what the body
// around folds and inlines already (`%const:` and `%inlining:`, C252); the
// globals it saw, `at` of them; and its own name, being inlined.
pub fn r_carried(mut env: Renv, mut acc: Renv) -> Renv {
    loop {
        if null_p(env) {
            return acc;
        } else {
            (env, acc) = (cdr(env), {
                let tagcase_ = car(env);
                match *tagcase_ {
                    Rbind::Rbind(n, l) => {
                        if (has_prefix_p(n, str_lit("%const:")) || has_prefix_p(n, str_lit("%inlining:"))) {
                            kayak_rt::heap_cons(car(env), acc)
                        } else {
                            acc
                        }
                    }
                }
            });
            continue;
        }
    }
}

pub fn r_inline_env(params: Renv, env: Renv, name: Str, at: i64) -> Renv {
    onto(params, kayak_rt::heap_cons(rbind(genv_name(), rl_seen(at)), kayak_rt::heap_cons(rbind(inlining_name(name), rl_loop()), r_carried(env, nil::<&'static Rbind>()))))
}

