pub fn r_written_p(k: i64, ms: Rmoves, late: List<&'static Rlate>) -> bool {
    if not(null_p(ms)) {
        (i64_eq(move_to(car(ms)), k) || r_written_p(k, cdr(ms), late))
    } else if null_p(late) {
        false
    } else {
        ({
            let tagcase_ = car(late);
            match *tagcase_ {
                Rlate::Rlate(r, x) => {
                    i64_eq(r, k)
                }
            }
        } || r_written_p(k, ms, cdr(late)))
    }
}

/// Each value made for a jump back to the start into its parameter's
/// place: a register's into REGi+1, a slot's into slot i.
pub fn r_self_moves(mut g: &'static Rgen, mut made: Rlocs, mut i: i64) -> () {
    loop {
        if null_p(made) {
            return ();
        } else {
            {
                let tagcase_ = car(made);
                match *tagcase_ {
                    Rloc::RlReg(r) => {
                        if i64_eq(r, i64_plus(i, 1i64)) {
                            ()
                        } else {
                            r_opnn(g, str_lit("movereg"), r, i64_plus(i, 1i64))
                        }
                    }
                    Rloc::RlSlot(s) => {
                        if i64_eq(s, i) {
                            ()
                        } else {
                            r_slot_move(g, s, i)
                        }
                    }
                    _ => {
                        let y = tagcase_;
                        r_decline(g)
                    }
                }
            };
            (made, i) = (cdr(made), i64_plus(i, 1i64));
            continue;
        }
    }
}

pub fn r_slot_args_of(g: &'static Rgen, ls: Rlocs) -> Rargs {
    if null_p(ls) {
        nil::<&'static Rarg>()
    } else {
        kayak_rt::heap_cons({
            let tagcase_ = car(ls);
            match *tagcase_ {
                Rloc::RlSlot(s) => {
                    a_slot(s)
                }
                _ => {
                    let y = tagcase_;
                    r_decline(g);
                    a_slot(0i64)
                }
            }
        }, r_slot_args_of(g, cdr(ls)))
    }
}

// A frame slot for each of a module's items, in order, by name.
pub fn r_module_slots(g: &'static Rgen, its: List<&'static Cmem>) -> Cenv {
    if null_p(its) {
        nil::<&'static Centry>()
    } else {
        let s = r_slot(g);
        kayak_rt::heap_cons(centry(cmem_name(car(its)), at_slot(s)), r_module_slots(g, cdr(its)))
    }
}

// Each frame slot as an operand, in order.
pub fn r_slot_args(ss: List<i64>) -> Rargs {
    if null_p(ss) {
        nil::<&'static Rarg>()
    } else {
        kayak_rt::heap_cons(a_slot(car(ss)), r_slot_args(cdr(ss)))
    }
}

// Item `n`'s lambda's scopes while it is made: each of `later` pending, and
// itself a loop if it only calls itself in loops.
pub fn r_module_own(mut n: Str, mut sc: &'static Rscope, mut later: Cenv, mut lbody: &'static Cx, mut nps: i64) -> &'static Rscope {
    loop {
        if null_p(later) {
            return sc;
        } else {
            let tagcase_ = car(later);
            match *tagcase_ {
                Centry::Centry(m, l) => {
                    let (loops, s) = ((string_eq_p(m, n) && c_loops_only(lbody, n, nps, true)), {
                        let tagcase_ = l;
                        match *tagcase_ {
                            Loc::AtSlot(i) => {
                                i
                            }
                            _ => {
                                let y = tagcase_;
                                the::<i64>(0i64)
                            }
                        }
                    });
                    let tagcase_ = sc;
                    match *tagcase_ {
                        Rscope::Rscope(env, te) => {
                            (sc, later) = (rscope(r_bind(m, if loops {
                                rl_loop()
                            } else {
                                rl_pending(s)
                            }, env), c_extend(m, if loops {
                                at_loop()
                            } else {
                                at_pending(s)
                            }, te)), cdr(later));
                            continue;
                        }
                    }
                }
            }
        }
    }
}

/// `x`'s value into RESULT; in tail position, returned: where its code
/// begins noted, and where the code after it, its parent's again,
/// does (C249, as the stack code's).
pub fn r_exp(g: &'static Rgen, x: &'static Cx, env: Renv, te: Cenv, tail: bool) -> () {
    let (p, here) = (cx_start(x), x_at(g_ctx(g)));
    let outer = get(here);
    if i64_gt(p, 0i64) {
        r_emit(g, ri_pos(p));
        set(here, p);
        r_exp_at(g, x, env, te, tail);
        set(here, outer);
        if i64_gt(outer, 0i64) {
            r_emit(g, ri_pos(outer))
        } else {
            ()
        }
    } else {
        r_exp_at(g, x, env, te, tail)
    }
}

pub fn r_exp_at(g: &'static Rgen, x: &'static Cx, env: Renv, te: Cenv, tail: bool) -> () {
    let k = r_known(env, x);
    if not(null_p(k)) {
        r_const_value(g, rconst_lit(car(k)), tail)
    } else {
        let tagcase_ = x;
        match *tagcase_ {
            Cx::XVar(n, a) => {
                r_var_value(g, r_where(env, n), n, tail);
                r_done(g, tail)
            }
            Cx::XStr(s, a) => {
                r_const_value(g, l_str(s), tail)
            }
            Cx::XFloat(b, a) => {
                r_const_value(g, l_f64(b), tail)
            }
            Cx::XSym(s, a) => {
                r_const_value(g, l_sym(s), tail)
            }
            Cx::XUnit(a) => {
                r_const_value(g, l_unit(), tail)
            }
            Cx::XInt(n, a) => {
                r_const_value(g, l_int(n), tail)
            }
            Cx::XBool(v, a) => {
                r_const_value(g, l_bool(v), tail)
            }
            Cx::XChar(v, a) => {
                r_const_value(g, l_char(v), tail)
            }
            Cx::XProj(y, a) => {
                r_exp(g, y, env, te, tail)
            }
            Cx::XRegion(k2, r, body, a) => {
                if (i64_eq(k2, 0i64) || i64_eq(k2, 3i64)) {
                    r_exp(g, body, env, te, tail)
                } else {
                    r_letregion(g, k2, r, body, env, te, tail)
                }
            }
            Cx::XIf(t, th, el, a) => {
                let kt = r_known(env, t);
                if not(null_p(kt)) {
                    r_exp(g, if r_const_false_p(car(kt)) {
                        el
                    } else {
                        th
                    }, env, te, tail)
                } else {
                    let (no, end) = (r_new_label(g), r_new_label(g));
                    r_branch_on(g, t, false, no, env, te);
                    r_exp(g, th, r_knowing(env, t, true), te, tail);
                    if tail {
                        ()
                    } else {
                        r_emit(g, ri_branch(str_lit("branch"), end))
                    };
                    r_emit(g, ri_label(no));
                    r_exp(g, el, r_knowing(env, t, false), te, tail);
                    r_emit(g, ri_label(end))
                }
            }
            Cx::XBegin(es, a) => {
                if null_p(es) {
                    r_const_value(g, l_unit(), tail)
                } else {
                    r_begin(g, es, env, te, tail)
                }
            }
            Cx::XLet(bs, body, a) => {
                r_let(g, bs, body, env, te, tail)
            }
            Cx::XExtract(p, i, a) => {
                r_exp(g, p, env, te, false);
                r_opn(g, str_lit("field"), i64_plus(i, 2i64));
                r_done(g, tail)
            }
            Cx::XApp(f, args, a) => {
                let tagcase_ = f;
                match *tagcase_ {
                    Cx::XLambda(ps, body, b) => {
                        if i64_eq(size(ps), size(args)) {
                            r_let(g, map2(lambda2s(move |p: Str, y: &'static Cx| {
                                cbind(p, y)
                            }), ps, args), body, env, te, tail)
                        } else {
                            r_app(g, f, args, a, env, te, tail)
                        }
                    }
                    _ => {
                        let y = tagcase_;
                        r_app(g, f, args, a, env, te, tail)
                    }
                }
            }
            Cx::XLambda(ps, body, a) => {
                r_lambda(g, ps, body, env, te, nil::<Str>(), nil::<&'static Cx>(), tail);
                r_done(g, tail)
            }
            Cx::XRlambda(r, l, a) => {
                let tagcase_ = l;
                match *tagcase_ {
                    Cx::XLambda(ps, body, b) => {
                        r_lambda(g, ps, body, env, te, nil::<Str>(), kayak_rt::heap_cons(r, kayak_rt::nil()), false);
                        r_done(g, tail)
                    }
                    _ => {
                        let y = tagcase_;
                        r_decline(g)
                    }
                }
            }
            Cx::XLetrec(bs, body, a) => {
                if (g_leaf(g) && not(r_all_p(r_join_flags(bs, body, tail)))) {
                    r_decline(g)
                } else {
                    r_letrec(g, bs, body, env, te, tail)
                }
            }
            Cx::XTagcase(s, arms, els, k, a) => {
                if i64_lt(k, 0i64) {
                    r_tagcase(g, s, arms, els, env, te, tail)
                } else {
                    r_flat_tagcase(g, k, s, arms, els, env, te, tail)
                }
            }
            Cx::XBloblet(op, i, args, a) => {
                r_bloblet(g, op, i, args, env, te);
                r_done(g, tail)
            }
            Cx::XModule(its, a) => {
                r_module(g, its, env, te, tail)
            }
            Cx::XWith(m, ns, ks, body, a) => {
                r_with(g, m, ns, ks, body, env, te, tail)
            }
            Cx::XReshape(y, ps, a) => {
                r_reshape(g, y, ps, env, te, tail)
            }
            Cx::XSum(t, v, a) => {
                r_prim(g, str_lit("%make-frozen"), kayak_rt::heap_cons(a_v(l_int(int_lit(36))), kayak_rt::heap_cons(a_v(l_sym(t)), kayak_rt::heap_cons(a_e(v), kayak_rt::nil()))), env, te);
                r_done(g, tail)
            }
            Cx::XProduct(fs, a) => {
                r_prim(g, str_lit("%make-frozen"), kayak_rt::heap_cons(a_v(l_int(int_lit(37))), r_exp_args(c_bound_exps(fs))), env, te);
                r_done(g, tail)
            }
            Cx::XPrompt(t, body, h, a) => {
                r_call_out(g, str_lit("cellular"), str_lit("prompt"), kayak_rt::heap_cons(a_e(t), kayak_rt::heap_cons(a_e(h), kayak_rt::heap_cons(a_thunk(body), kayak_rt::nil()))), env, te);
                r_done(g, tail)
            }
            _ => {
                let y = tagcase_;
                r_decline(g)
            }
        }
    }
}

/// The region's name bound, as a `let`'s, to a region entered (never in
/// a leaf), and left with the body's value, which is so not in tail
/// position (C259, Fixpt's `r-letregion`).
pub fn r_letregion(g: &'static Rgen, k: i64, r: Str, body: &'static Cx, env: Renv, te: Cenv, tail: bool) -> () {
    if g_leaf(g) {
        r_decline(g)
    } else {
        let (regs, slots) = (get(g_nreg(g)), get(g_nslot(g)));
        r_prim(g, if i64_eq(k, 1i64) {
            str_lit("%region-enter")
        } else {
            str_lit("%reap-enter")
        }, nil::<&'static Rarg>(), env, te);
        {
            let h = r_keep_in_slot(g);
            r_exp(g, body, r_bind(r, rl_slot(h), env), r_local(te, r), false);
            let v = r_keep_in_slot(g);
            r_prim(g, str_lit("%region-exit"), kayak_rt::heap_cons(a_slot(h), kayak_rt::heap_cons(a_slot(v), kayak_rt::nil())), env, te);
            r_done(g, tail)
        };
        r_restore(g, regs, slots)
    }
}

/// A bloblet form, by its field index or, a blobref's, the operand the
/// checker found: a scalar's layout, an array's, a flat sum's.
pub fn r_bloblet(g: &'static Rgen, op: Str, i: i64, args: Cxs, env: Renv, te: Cenv) -> () {
    let all = r_exp_args(args);
    if string_eq_p(op, str_lit("bloblet-ref")) {
        r_exp(g, car(args), env, te, false);
        r_opn(g, str_lit("field"), i64_plus(i, 2i64))
    } else if string_eq_p(op, str_lit("make-bloblet")) {
        r_prim(g, str_lit("%make-bloblet"), all, env, te)
    } else if string_eq_p(op, str_lit("rmake-bloblet")) {
        r_prim(g, str_lit("%region-make-bloblet"), all, env, te)
    } else if string_eq_p(op, str_lit("bloblet-set!")) {
        r_prim(g, str_lit("%bloblet-set!"), kayak_rt::heap_cons(a_e(car(args)), kayak_rt::heap_cons(a_v(l_int(i64_to_int(i64_plus(i, 2i64)))), kayak_rt::heap_cons(a_e(second_cx(args)), kayak_rt::nil()))), env, te);
        r_unit(g)
    } else if string_eq_p(op, str_lit("bloblet-byte")) {
        r_prim(g, str_lit("%bloblet-byte"), all, env, te)
    } else if string_eq_p(op, str_lit("bloblet-set-byte!")) {
        r_prim(g, str_lit("%bloblet-set-byte!"), all, env, te);
        r_unit(g)
    } else if string_eq_p(op, str_lit("bloblet-bytes")) {
        r_prim(g, str_lit("%bloblet-bytes"), all, env, te)
    } else if string_eq_p(op, str_lit("blobref-at")) {
        {
            let tagcase_ = second_cx(args);
            match *tagcase_ {
                Cx::XInt(k, a) => {
                    if (_gt_eq(k, int_lit(0)) && _lt(k, int_lit(67108864))) {
                        r_prim(g, str_lit("%suffix-ref"), kayak_rt::heap_cons(a_e(car(args)), kayak_rt::heap_cons(a_v(l_int(k)), kayak_rt::nil())), env, te)
                    } else {
                        r_prim(g, str_lit("%suffix-ref"), all, env, te)
                    }
                }
                _ => {
                    let y = tagcase_;
                    r_prim(g, str_lit("%suffix-ref"), all, env, te)
                }
            }
        };
        r_fits(g, i)
    } else if string_eq_p(op, str_lit("blobref+")) {
        r_prim(g, str_lit("%suffix-ref+"), all, env, te);
        r_fits(g, i)
    } else if string_eq_p(op, str_lit("%blobref-field")) {
        r_prim(g, str_lit("%suffix-ref+"), kayak_rt::heap_cons(a_e(car(args)), kayak_rt::heap_cons(a_v(l_int(i64_to_int(i))), kayak_rt::nil())), env, te)
    } else if string_eq_p(op, str_lit("blobref-owner")) {
        r_prim(g, str_lit("%suffix-ref-owner"), all, env, te)
    } else if string_eq_p(op, str_lit("blobref-offset")) {
        r_prim(g, str_lit("%suffix-ref-offset"), all, env, te)
    } else if i64_lt(i, 0i64) {
        r_decline(g)
    } else if string_eq_p(op, str_lit("blobref-get")) {
        r_prim(g, str_lit("%fx26-suffix-ref-get"), kayak_rt::heap_cons(a_e(car(args)), kayak_rt::heap_cons(a_v(l_int(i64_to_int(i))), kayak_rt::nil())), env, te)
    } else if string_eq_p(op, str_lit("blobref-length")) {
        r_prim(g, str_lit("%fx26-suffix-ref-length"), kayak_rt::heap_cons(a_e(car(args)), kayak_rt::heap_cons(a_v(l_int(i64_to_int(i))), kayak_rt::nil())), env, te)
    } else if string_eq_p(op, str_lit("blobref-index")) {
        r_prim3(g, str_lit("%fx26-blobref-index"), car(args), i, second_cx(args), env, te)
    } else if string_eq_p(op, str_lit("blobref-set!")) {
        r_prim3(g, str_lit("%fx26-suffix-ref-set!"), car(args), i, second_cx(args), env, te)
    } else if string_eq_p(op, str_lit("blobref-variant!")) {
        r_prim3(g, str_lit("%fx26-flat-variant!"), car(args), i, second_cx(args), env, te)
    } else {
        r_decline(g)
    }
}

/// RESULT := runtime primitive `name`, one that never collects, of `a`'s
/// value, constant `x` and `b`'s (`prim3imm`): `a` kept in its place
/// while `b` is made into a register of its own.
pub fn r_prim3(g: &'static Rgen, name: Str, a: &'static Cx, x: i64, b: &'static Cx, env: Renv, te: Cenv) -> () {
    let (regs, slots) = (get(g_nreg(g)), get(g_nslot(g)));
    r_exp(g, a, env, te, false);
    {
        let at = r_place_value(g);
        let k = {
            r_exp(g, b, env, te, false);
            r_reg(g)
        };
        r_opn(g, str_lit("setreg"), k);
        r_get(g, at);
        r_ins(g, str_lit("prim3imm"), kayak_rt::heap_cons(o_prim(name), kayak_rt::heap_cons(o_lit(l_int(i64_to_int(x))), kayak_rt::heap_cons(o_int(k), kayak_rt::nil()))))
    };
    r_restore(g, regs, slots)
}

pub fn r_imm_prim(g: &'static Rgen, name: Str, v: &'static Lit) -> () {
    r_ins(g, str_lit("prim2imm"), kayak_rt::heap_cons(o_prim(name), kayak_rt::heap_cons(o_lit(v), kayak_rt::nil())))
}

/// A new blobref's flat's `size` bytes checked in the suffix, in line;
/// declined where the checker noted none.
pub fn r_fits(g: &'static Rgen, size: i64) -> () {
    if i64_lt(size, 0i64) {
        r_decline(g)
    } else if i64_gt(size, 1i64) {
        r_imm_prim(g, str_lit("%fx26-suffix-fits"), l_int(i64_to_int(size)))
    } else {
        ()
    }
}

/// The blobref and its tag, a label, kept in places (registers in a
/// leaf); each arm's name a blobref to its variant, `k / 256` bytes
/// along; no arm for the tag a failure. No call-outs.
pub fn r_flat_tagcase(g: &'static Rgen, k: i64, s: &'static Cx, arms: List<&'static Carm>, els: Cbinds, env: Renv, te: Cenv, tail: bool) -> () {
    let (regs, slots) = (get(g_nreg(g)), get(g_nslot(g)));
    {
        let sc = r_scrutinee_place(g, s, env, te);
        let tag = {
            r_imm_prim(g, str_lit("%fx26-flat-tag"), l_int(i64_to_int(k)));
            r_place_value(g)
        };
        let end = r_new_label(g);
        r_flat_arms(g, k, arms, sc, tag, end, regs, slots, env, te, tail);
        if null_p(els) {
            r_get(g, tag);
            r_ins(g, str_lit("prim1"), kayak_rt::heap_cons(o_prim(str_lit("%fx26-flat-no-arm")), kayak_rt::nil()));
            r_done(g, tail)
        } else {
            let tagcase_ = car(els);
            match *tagcase_ {
                Cbind::Cbind(n, x) => {
                    r_exp(g, x, r_bind(n, sc, env), r_local(te, n), tail)
                }
            }
        };
        r_emit(g, ri_label(end))
    };
    r_restore(g, regs, slots)
}

pub fn r_flat_arms(mut g: &'static Rgen, mut k: i64, mut arms: List<&'static Carm>, mut sc: &'static Rloc, mut tag: &'static Rloc, mut end: i64, mut regs0: i64, mut slots0: i64, mut env: Renv, mut te: Cenv, mut tail: bool) -> () {
    loop {
        if null_p(arms) {
            return ();
        } else {
            let tagcase_ = car(arms);
            match *tagcase_ {
                Carm::Carm(name, whole, ns, body) => {
                    let next = r_new_label(g);
                    r_get(g, tag);
                    r_op2imm(g, str_lit("eq"), if i64_eq(i64_remainder(i64_quotient(k, 8i64), 2i64), 1i64) {
                        l_int(i64_to_int(digits_i64(string_chars(name), 0i64)))
                    } else {
                        l_sym(name)
                    });
                    r_emit(g, ri_branch(str_lit("branchf"), next));
                    {
                        let (regs, slots) = (get(g_nreg(g)), get(g_nslot(g)));
                        r_get(g, sc);
                        r_imm_prim(g, str_lit("%suffix-ref+"), l_int(i64_to_int(i64_quotient(k, 256i64))));
                        r_restore(g, regs0, slots0);
                        {
                            let at = r_place_value(g);
                            r_exp(g, body, r_bind(car(ns), at, env), r_local(te, car(ns)), tail)
                        };
                        r_restore(g, regs, slots)
                    };
                    if tail {
                        ()
                    } else {
                        r_emit(g, ri_branch(str_lit("branch"), end))
                    };
                    r_emit(g, ri_label(next));
                    arms = cdr(arms);
                    continue;
                }
            }
        }
    }
}

/// `s`'s value into RESULT, and where it is kept: where it is already,
/// if a variable in a register or the frame; else a place of its own.
pub fn r_scrutinee_place(g: &'static Rgen, s: &'static Cx, env: Renv, te: Cenv) -> &'static Rloc {
    let v = r_plain_var_loc(env, s);
    if (not(null_p(v)) && {
        let tagcase_ = car(v);
        match *tagcase_ {
            Rloc::RlReg(r) => {
                true
            }
            Rloc::RlSlot(n) => {
                true
            }
            _ => {
                let y = tagcase_;
                false
            }
        }
    }) {
        r_get(g, car(v));
        car(v)
    } else {
        r_exp(g, s, env, te, false);
        r_place_value(g)
    }
}

/// A module: its items made in frame slots in order, as its stack code
/// makes them; then the product of its values. Declined in a leaf.
pub fn r_module(g: &'static Rgen, its: List<&'static Cmem>, env: Renv, te: Cenv, tail: bool) -> () {
    if g_leaf(g) {
        r_decline(g)
    } else {
        let slots = get(g_nslot(g));
        let later = r_module_slots(g, its);
        let vals = r_module_make(g, its, env, te, later, nil::<&'static Wait>(), nil::<i64>());
        r_prim(g, str_lit("%make-frozen"), kayak_rt::heap_cons(a_v(l_int(int_lit(37))), r_slot_args(reverse(vals))), env, te);
        set(g_nslot(g), slots);
        r_done(g, tail)
    }
}

/// Items `its` made in their slots, `later`, in order, as a `letrec*`'s:
/// a typed lambda naming an item not made yet captures it once it is
/// made; `ws` the closures waiting, `vals` the slots of the values the
/// module gives so far (newest first).
pub fn r_module_make(mut g: &'static Rgen, mut its: List<&'static Cmem>, mut env: Renv, mut te: Cenv, mut later: Cenv, mut ws: List<&'static Wait>, mut vals: List<i64>) -> List<i64> {
    loop {
        if null_p(its) {
            return vals;
        } else {
            let tagcase_ = car(its);
            match *tagcase_ {
                Cmem::Cmem(n, x, k, lam, at) => {
                    let s = {
                        let tagcase_ = car(later);
                        match *tagcase_ {
                            Centry::Centry(m, l) => {
                                let tagcase_ = l;
                                match *tagcase_ {
                                    Loc::AtSlot(i) => {
                                        i
                                    }
                                    _ => {
                                        let y = tagcase_;
                                        the::<i64>(0i64)
                                    }
                                }
                            }
                        }
                    };
                    let ps = if (lam && c_names_any_p(x, later)) {
                        r_module_closure(g, n, x, env, te, later)
                    } else {
                        r_exp(g, x, env, te, false);
                        the::<Rpatches>(nil::<&'static Rpatch>())
                    };
                    let waits = {
                        r_opn(g, str_lit("setstk"), s);
                        onto(ws, map(lambda1s(move |p: &'static Rpatch| {
                            let tagcase_ = p;
                            match *tagcase_ {
                                Rpatch::Rpatch(j, t) => {
                                    wait(s, j, t)
                                }
                            }
                        }), ps))
                    };
                    r_give_waiting(g, waits, s);
                    (its, env, te, later, ws, vals) = (cdr(its), r_bind(n, rl_slot(s), env), r_local(te, n), cdr(later), waits, if i64_gt(k, 0i64) {
                        kayak_rt::heap_cons(s, vals)
                    } else {
                        vals
                    });
                    continue;
                }
            }
        }
    }
}

/// Item `n`'s lambda `x`, naming items of `later` not made yet: those
/// captured as a `letrec`'s siblings are, to be given once made.
pub fn r_module_closure(g: &'static Rgen, n: Str, x: &'static Cx, env: Renv, te: Cenv, later: Cenv) -> Rpatches {
    let l = lambda_of(x);
    if null_p(l) {
        r_decline(g);
        nil::<&'static Rpatch>()
    } else {
        let tagcase_ = car(l);
        match *tagcase_ {
            Lparts::Lparts(ps, lbody, region) => {
                let tagcase_ = r_module_own(n, rscope(env, te), later, lbody, size(ps));
                match *tagcase_ {
                    Rscope::Rscope(e2, te2) => {
                        r_lambda(g, ps, lbody, e2, te2, kayak_rt::heap_cons(n, kayak_rt::nil()), region, false)
                    }
                }
            }
        }
    }
}

/// Each closure of `ws` waiting for slot `s`, given it.
pub fn r_give_waiting(mut g: &'static Rgen, mut ws: List<&'static Wait>, mut s: i64) -> () {
    loop {
        if null_p(ws) {
            return ();
        } else {
            {
                let tagcase_ = car(ws);
                match *tagcase_ {
                    Wait::Wait(at, j, t) => {
                        if i64_eq(t, s) {
                            r_opnn(g, str_lit("load"), 1i64, s);
                            r_opn(g, str_lit("stack"), at);
                            r_opnn(g, str_lit("setfield"), i64_plus(3i64, j), 1i64)
                        } else {
                            ()
                        }
                    }
                }
            };
            ws = cdr(ws);
            continue;
        }
    }
}

/// `with`: the module's values the body names, by position, each kept
/// as a `let`'s value is (in a leaf, in a register); then the body.
pub fn r_with(g: &'static Rgen, m: &'static Cx, ns: Strings, ks: List<i64>, body: &'static Cx, env: Renv, te: Cenv, tail: bool) -> () {
    let (regs, slots) = (get(g_nreg(g)), get(g_nslot(g)));
    {
        let tagcase_ = r_with_fields(g, m, ns, ks, c_free(body, nil::<Str>(), nil::<Str>()), env, rscope(env, te));
        match *tagcase_ {
            Rscope::Rscope(e2, te2) => {
                r_exp(g, body, e2, te2, tail)
            }
        }
    };
    r_restore(g, regs, slots)
}

pub fn r_with_fields(mut g: &'static Rgen, mut m: &'static Cx, mut ns: Strings, mut ks: List<i64>, mut fv: Strings, mut env: Renv, mut sc: &'static Rscope) -> &'static Rscope {
    loop {
        if (null_p(ns) || null_p(ks)) {
            return sc;
        } else {
            if string_member_p(car(ns), fv) {
                let l = {
                    r_module_value(g, m, env);
                    r_opn(g, str_lit("field"), i64_plus(car(ks), 2i64));
                    r_keep(g, g_leaf(g))
                };
                let tagcase_ = sc;
                match *tagcase_ {
                    Rscope::Rscope(e2, te2) => {
                        (ns, ks, sc) = (cdr(ns), cdr(ks), rscope(r_bind(car(ns), l, e2), r_local(te2, car(ns))));
                        continue;
                    }
                }
            } else {
                (ns, ks) = (cdr(ns), cdr(ks));
                continue;
            }
        }
    }
}

/// Module `m`'s value into RESULT, from where `env` has it; declined if
/// it is not a name in a place.
pub fn r_module_value(g: &'static Rgen, m: &'static Cx, env: Renv) -> () {
    let tagcase_ = m;
    match *tagcase_ {
        Cx::XVar(n, a) => {
            let l = r_where(env, n);
            if null_p(l) {
                r_decline(g)
            } else {
                let tagcase_ = car(l);
                match *tagcase_ {
                    Rloc::RlReg(k) => {
                        r_opn(g, str_lit("reg"), k)
                    }
                    Rloc::RlSlot(s) => {
                        r_opn(g, str_lit("stack"), s)
                    }
                    Rloc::RlFree(i) => {
                        r_opn(g, str_lit("lexical"), i)
                    }
                    Rloc::RlGlobal(c) => {
                        r_ins(g, str_lit("global"), kayak_rt::heap_cons(o_global(c), kayak_rt::nil()))
                    }
                    _ => {
                        let y = tagcase_;
                        r_decline(g)
                    }
                }
            }
        }
        _ => {
            let y = tagcase_;
            r_decline(g)
        }
    }
}

/// A module reshaped: kept in a slot, the values the type wanted has
/// (by path) each into a slot, and a product of them. Declined in a
/// leaf.
pub fn r_reshape(g: &'static Rgen, y: &'static Cx, ps: Paths, env: Renv, te: Cenv, tail: bool) -> () {
    if g_leaf(g) {
        r_decline(g)
    } else {
        let slots = get(g_nslot(g));
        let m = {
            r_exp(g, y, env, te, false);
            r_keep_in_slot(g)
        };
        let args = r_reshape_fields(g, m, ps);
        r_prim(g, str_lit("%make-frozen"), kayak_rt::heap_cons(a_v(l_int(int_lit(37))), args), env, te);
        set(g_nslot(g), slots);
        r_done(g, tail)
    }
}

pub fn r_reshape_fields(g: &'static Rgen, m: i64, ps: Paths) -> Rargs {
    if null_p(ps) {
        nil::<&'static Rarg>()
    } else {
        let s = {
            r_opn(g, str_lit("stack"), m);
            r_fields_in(g, car(ps));
            r_keep_in_slot(g)
        };
        kayak_rt::heap_cons(a_slot(s), r_reshape_fields(g, m, cdr(ps)))
    }
}

pub fn r_fields_in(mut g: &'static Rgen, mut ks: List<i64>) -> () {
    loop {
        if null_p(ks) {
            return ();
        } else {
            r_opn(g, str_lit("field"), i64_plus(car(ks), 2i64));
            ks = cdr(ks);
            continue;
        }
    }
}

/// Variable `n`'s value into RESULT, from where it is; if nowhere,
/// `nil`, or a standard operation as a value.
pub fn r_var_value(g: &'static Rgen, l: Rlocs, n: Str, tail: bool) -> () {
    if null_p(l) {
        if std_nil_name_p(std_named(n)) {
            r_const(g, l_nil())
        } else {
            r_standard_value(g, std_named(n), tail)
        }
    } else {
        let tagcase_ = car(l);
        match *tagcase_ {
            Rloc::RlReg(k) => {
                r_opn(g, str_lit("reg"), k)
            }
            Rloc::RlSlot(s) => {
                r_opn(g, str_lit("stack"), s)
            }
            Rloc::RlFree(i) => {
                r_opn(g, str_lit("lexical"), i)
            }
            Rloc::RlGlobal(c) => {
                r_ins(g, str_lit("global"), kayak_rt::heap_cons(o_global(c), kayak_rt::nil()))
            }
            _ => {
                let y = tagcase_;
                r_decline(g)
            }
        }
    }
}

/// A standard operation as a value: a closure of the word the stack
/// code made for it. A leaf makes one only in tail position, and a
/// `vsubr`'s, given to `%fx26-vlambda`, never.
pub fn r_standard_value(g: &'static Rgen, name: Str, tail: bool) -> () {
    if (not(string_member_p(name, get(cg_standard_words()))) || (g_leaf(g) && (not(tail) || c_vsubr_p(name)))) {
        r_decline(g)
    } else {
        r_ins(g, str_lit("lambda"), kayak_rt::heap_cons(o_word(name), kayak_rt::heap_cons(o_int(0i64), kayak_rt::nil())));
        if c_vsubr_p(name) {
            r_opn(g, str_lit("setreg"), 1i64);
            r_ins(g, str_lit("prim"), kayak_rt::heap_cons(o_prim(str_lit("%fx26-vlambda")), kayak_rt::heap_cons(o_int(1i64), kayak_rt::nil())))
        } else {
            ()
        }
    }
}

/// Code that goes to `label` if `x` is `when` (true: anything but #f),
/// and on if not: `and`, `or` and `not` make no boolean.
pub fn r_branch_on(mut g: &'static Rgen, mut x: &'static Cx, mut when: bool, mut label: i64, mut env: Renv, mut te: Cenv) -> () {
    loop {
        let tagcase_ = x;
        match *tagcase_ {
            Cx::XProj(y, a) => {
                x = y;
                continue;
            }
            Cx::XApp(f, args, a) => {
                if (string_eq_p(r_standard_name(env, f), str_lit("not")) && i64_eq(size(args), 1i64)) {
                    (x, when) = (car(args), not(when));
                    continue;
                } else {
                    return r_branch_plain(g, x, when, label, env, te);
                }
            }
            Cx::XIf(t, th, el, a) => {
                let (tc, ec) = (r_known(env, th), r_known(env, el));
                if (not(null_p(tc)) && r_holds_p(tc, when)) {
                    r_branch_on(g, t, true, label, env, te);
                    x = el;
                    continue;
                } else if not(null_p(tc)) {
                    return r_branch_past(g, t, true, el, when, label, env, te);
                } else if (not(null_p(ec)) && r_holds_p(ec, when)) {
                    r_branch_on(g, t, false, label, env, te);
                    x = th;
                    continue;
                } else if not(null_p(ec)) {
                    return r_branch_past(g, t, false, th, when, label, env, te);
                } else {
                    let (no, end) = (r_new_label(g), r_new_label(g));
                    r_branch_on(g, t, false, no, env, te);
                    r_branch_on(g, th, when, label, env, te);
                    r_emit(g, ri_branch(str_lit("branch"), end));
                    r_emit(g, ri_label(no));
                    r_branch_on(g, el, when, label, env, te);
                    return r_emit(g, ri_label(end));
                }
            }
            _ => {
                let y = tagcase_;
                return r_branch_plain(g, x, when, label, env, te);
            }
        }
    }
}

pub fn r_branch_past(g: &'static Rgen, t: &'static Cx, sense: bool, x: &'static Cx, when: bool, label: i64, env: Renv, te: Cenv) -> () {
    let skip = r_new_label(g);
    r_branch_on(g, t, sense, skip, env, te);
    r_branch_on(g, x, when, label, env, te);
    r_emit(g, ri_label(skip))
}

pub fn r_branch_plain(g: &'static Rgen, x: &'static Cx, when: bool, label: i64, env: Renv, te: Cenv) -> () {
    let k = r_known(env, x);
    if not(null_p(k)) {
        if r_holds_p(k, when) {
            r_emit(g, ri_branch(str_lit("branch"), label))
        } else {
            ()
        }
    } else {
        r_exp(g, x, env, te, false);
        r_emit(g, ri_branch(if when {
            str_lit("brancht")
        } else {
            str_lit("branchf")
        }, label))
    }
}

pub fn r_begin(mut g: &'static Rgen, mut es: Cxs, mut env: Renv, mut te: Cenv, mut tail: bool) -> () {
    loop {
        if null_p(cdr(es)) {
            return r_exp(g, car(es), env, te, tail);
        } else {
            r_exp(g, car(es), env, te, false);
            es = cdr(es);
            continue;
        }
    }
}

/// Where `x`'s value is: a constant, as itself; else made and kept, in a
/// register if `reg`, else a frame slot.
pub fn r_value_loc(g: &'static Rgen, x: &'static Cx, env: Renv, te: Cenv, reg: bool) -> &'static Rloc {
    let k = r_known(env, x);
    if null_p(k) {
        r_exp(g, x, env, te, false);
        r_keep(g, reg)
    } else {
        rl_const(car(k))
    }
}

pub fn r_let_bind(g: &'static Rgen, bs: Cbinds, env: Renv, te: Cenv, flags: List<bool>) -> Renv {
    if null_p(bs) {
        nil::<&'static Rbind>()
    } else {
        let tagcase_ = car(bs);
        match *tagcase_ {
            Cbind::Cbind(n, x) => {
                let l = r_value_loc(g, x, env, te, car(flags));
                kayak_rt::heap_cons(rbind(n, l), r_let_bind(g, cdr(bs), env, te, cdr(flags)))
            }
        }
    }
}

/// Each value made, in the scope outside, and kept in a register where
/// no call comes before the body is done with it (else the frame).
pub fn r_let(g: &'static Rgen, bs: Cbinds, body: &'static Cx, env: Renv, te: Cenv, tail: bool) -> () {
    let regs = get(g_nreg(g));
    let slots = get(g_nslot(g));
    let body_collects = r_collects_here_p(g, body, r_local_names(te, bs), tail);
    let flags = r_in_regs(g, c_bound_exps(bs), 0i64, te, body_collects);
    let bound = r_let_bind(g, bs, env, te, flags);
    r_exp(g, body, r_bind_all(bound, env), r_local_all(bound, te), tail);
    r_restore(g, regs, slots)
}

pub fn r_app(g: &'static Rgen, f: &'static Cx, args: Cxs, a: i64, env: Renv, te: Cenv, tail: bool) -> () {
    let (n, own) = (size(args), r_own_self(g, env, f, args));
    if not(null_p(r_join_of(env, f))) {
        r_jump(g, car(r_join_of(env, f)), args, env, te, tail)
    } else if (tail && r_self_known_p(g, f, n, te)) {
        r_loop(g, args, env, te)
    } else if not(null_p(own)) {
        r_self_guarded(g, car(own), x_own_start(g_ctx(g)), f, args, a, env, te, tail)
    } else {
        let name = r_standard_name(env, f);
        if string_eq_p(name, str_lit("")) {
            r_call(g, f, args, a, env, te, tail)
        } else if (string_eq_p(name, str_lit("%quote")) && i64_eq(n, 1i64)) {
            let cell = c_quoted_cell(car(args));
            if null_p(cell) {
                r_prim(g, str_lit("%fx26-intern-datum"), r_exp_args(args), env, te);
                r_done(g, tail)
            } else {
                r_const_value(g, quoted_interned(car(cell)), tail)
            }
        } else if (tail && string_eq_p(name, str_lit("with-mark")) && i64_eq(n, 3i64)) {
            r_args(g, r_exp_args(args), env, te, nil::<&'static Cx>());
            r_leave(g);
            r_ins(g, str_lit("cellular"), kayak_rt::heap_cons(o_prim(str_lit("withmark-tail")), kayak_rt::heap_cons(o_int(3i64), kayak_rt::nil())));
            r_op0(g, str_lit("return"))
        } else if (string_eq_p(name, str_lit("apply")) && i64_eq(n, 2i64)) {
            r_apply(g, args, env, te, tail)
        } else if not(null_p(r_identity_arg(env, name, args))) {
            r_exp(g, car(r_identity_arg(env, name, args)), env, te, tail)
        } else {
            r_standard_app(g, name, args, env, te);
            r_done(g, tail)
        }
    }
}

pub fn r_standard_app(g: &'static Rgen, name: Str, args: Cxs, env: Renv, te: Cenv) -> () {
    let tagcase_ = r_standard(name, size(args));
    match *tagcase_ {
        Rstd::SOp2(r, swap, negate) => {
            let x = car(args);
            let y = car(cdr(args));
            let split = if (r_add_name_p(name) && (r_adds_p(env, x) || r_adds_p(env, y))) {
                r_split_app(env, name, args)
            } else {
                nil::<&'static Rsplit>()
            };
            let core = if null_p(split) {
                nil::<&'static Cx>()
            } else {
                let tagcase_ = car(split);
                match *tagcase_ {
                    Rsplit::Rsplit(c, k) => {
                        c
                    }
                }
            };
            let literal = r_literal_p(x);
            let commutes = string_member_p(r, kayak_rt::heap_cons(str_lit("int-add"), kayak_rt::heap_cons(str_lit("eq"), kayak_rt::heap_cons(str_lit("int-eq"), kayak_rt::nil()))));
            let free_x = (swap && r_free_operand_p(env, x));
            let free_y = (swap && not(free_x) && r_free_operand_p(env, y));
            if r_deeper_p(core, x, y) {
                r_exp(g, car(core), env, te, false);
                r_add_imm(g, {
                    let tagcase_ = car(split);
                    match *tagcase_ {
                        Rsplit::Rsplit(c, k) => {
                            k
                        }
                    }
                })
            } else if (swap && not(free_x) && not(free_y)) {
                r_binary_swapped(g, r, x, y, env, te)
            } else if (swap || (commutes && literal && null_p(r_known(env, y)))) {
                r_binary(g, r, y, x, env, te)
            } else {
                r_binary(g, r, x, y, env, te)
            };
            if negate {
                r_negate(g)
            } else {
                ()
            }
        }
        Rstd::SOp1(r) => {
            r_exp(g, car(args), env, te, false);
            r_ins(g, str_lit("op1"), kayak_rt::heap_cons(o_prim(r), kayak_rt::nil()))
        }
        Rstd::SOp2imm(r, v) => {
            r_exp(g, car(args), env, te, false);
            r_op2imm(g, r, v)
        }
        Rstd::SField(k) => {
            r_exp(g, car(args), env, te, false);
            r_opn(g, str_lit("field"), k)
        }
        Rstd::SPrim(p) => {
            r_call_out(g, str_lit("prim"), p, r_exp_args(args), env, te)
        }
        Rstd::SPure(p) => {
            if null_p(cdr(args)) {
                r_exp(g, car(args), env, te, false);
                r_ins(g, str_lit("prim1"), kayak_rt::heap_cons(o_prim(p), kayak_rt::nil()))
            } else {
                r_pure2(g, p, car(args), car(cdr(args)), env, te)
            }
        }
        Rstd::SCellular(r) => {
            r_call_out(g, str_lit("cellular"), r, r_exp_args(args), env, te)
        }
        Rstd::SIdentity() => {
            r_exp(g, car(args), env, te, false)
        }
        Rstd::SSet() => {
            let tagcase_ = r_operands(g, car(args), car(cdr(args)), env, te, false);
            match *tagcase_ {
                Roperands::RopReg(k) => {
                    r_opnn(g, str_lit("setfield"), 2i64, k);
                    r_unit(g)
                }
                _ => {
                    let y = tagcase_;
                    r_decline(g)
                }
            }
        }
        Rstd::SSpecial(what) => {
            r_special(g, what, args, env, te)
        }
        Rstd::SList() => {
            r_list(g, args, env, te)
        }
        _ => {
            let y = tagcase_;
            r_decline(g)
        }
    }
}

/// A call: the arguments into REG1…REGn, the procedure in RESULT.
pub fn r_call(g: &'static Rgen, f: &'static Cx, args: Cxs, a: i64, env: Renv, te: Cenv, tail: bool) -> () {
    let n = size(args);
    let u = r_unrolled(env, f, args);
    let i = if null_p(u) {
        r_inlined(env, f, size(args))
    } else {
        u
    };
    if not(null_p(i)) {
        if (not(x_assuming(g_ctx(g))) && g_leaf(g)) {
            r_decline(g)
        } else {
            r_inline(g, car(i), not(null_p(u)), f, args, a, env, te, tail)
        }
    } else if g_leaf(g) {
        if (tail && i64_lt(n, register_regs())) {
            r_leaf_tail_call(g, f, args, a, env, te)
        } else {
            r_decline(g)
        }
    } else if (not(tail) && r_self_known_p(g, f, n, te)) {
        r_args(g, r_exp_args(args), env, te, nil::<&'static Cx>());
        r_opn(g, str_lit("invokeself"), n)
    } else {
        r_args(g, r_exp_args(args), env, te, kayak_rt::heap_cons(f, kayak_rt::nil()));
        r_invoke(g, n, tail, r_conv_at(a))
    }
}

/// A call of a small global procedure, inlined (C252, Fixpt's
/// `r-inline`): the arguments made and kept (one a variable in the frame
/// or the closure, or a constant, used where it is); then, if the global
/// still holds a closure of the word its body was compiled to, the body,
/// in a scope of its own where the parameters are the arguments and the
/// globals those it saw; else the call. A redefinition writes the
/// global: the call.
pub fn r_inline(g: &'static Rgen, i: &'static Rinline, unrolled: bool, f: &'static Cx, args: Cxs, a: i64, env: Renv, te: Cenv, tail: bool) -> () {
    let tagcase_ = i;
    match *tagcase_ {
        Rinline::Rinline(name, ps, body, at) => {
            let regs = get(g_nreg(g));
            let slots = get(g_nslot(g));
            let bound = r_inline_args(g, ps, args, env, te);
            let call = r_new_label(g);
            let end = r_new_label(g);
            let assumed = ((unrolled && not(null_p(r_local_loc(env, inlining_name(name))))) || r_assume(g, name));
            if assumed {
                ()
            } else {
                r_guard(g, name, call)
            };
            {
                let tagcase_ = bound;
                match *tagcase_ {
                    Rbound::Rbound(benv, bte, bargs) => {
                        r_exp(r_unknowing(g), body, r_inline_env(benv, env, name, at), bte, tail);
                        if assumed {
                            ()
                        } else {
                            if tail {
                                ()
                            } else {
                                r_emit(g, ri_branch(str_lit("branch"), end))
                            };
                            r_emit(g, ri_label(call));
                            r_args(g, bargs, env, te, kayak_rt::heap_cons(f, kayak_rt::nil()));
                            r_invoke(g, size(args), tail, r_conv_at(a));
                            r_emit(g, ri_label(end))
                        }
                    }
                }
            };
            r_restore(g, regs, slots)
        }
    }
}

/// Each parameter bound to its argument, in order: where the body finds
/// it, the body's scope, and the call's arguments where the guard
/// fails.
pub fn r_inline_args(g: &'static Rgen, ps: Strings, args: Cxs, env: Renv, te: Cenv) -> &'static Rbound {
    if (null_p(ps) || null_p(args)) {
        rbound(nil::<&'static Rbind>(), nil::<&'static Centry>(), nil::<&'static Rarg>())
    } else {
        let p = car(ps);
        let x = car(args);
        let k = r_known(env, x);
        let l = if null_p(k) {
            r_var_loc(env, x)
        } else {
            the::<Rlocs>(kayak_rt::heap_cons(rl_const(car(k)), kayak_rt::nil()))
        };
        let keeps = (not(null_p(l)) && {
            let tagcase_ = car(l);
            match *tagcase_ {
                Rloc::RlSlot(s) => {
                    true
                }
                Rloc::RlFree(j) => {
                    true
                }
                Rloc::RlConst(c) => {
                    true
                }
                Rloc::RlReg(r) => {
                    x_assuming(g_ctx(g))
                }
                _ => {
                    let y = tagcase_;
                    false
                }
            }
        });
        let kept = if keeps {
            l
        } else {
            nil::<&'static Rloc>()
        };
        let here = if null_p(kept) {
            r_exp(g, x, env, te, false);
            r_keep(g, g_leaf(g))
        } else {
            car(kept)
        };
        let arg = if not(null_p(k)) {
            a_v(rconst_lit(car(k)))
        } else if null_p(kept) {
            let tagcase_ = here;
            match *tagcase_ {
                Rloc::RlSlot(s) => {
                    a_slot(s)
                }
                _ => {
                    let y = tagcase_;
                    a_e(x)
                }
            }
        } else {
            a_e(x)
        };
        let tagcase_ = r_inline_args(g, cdr(ps), cdr(args), env, te);
        match *tagcase_ {
            Rbound::Rbound(benv, bte, bargs) => {
                rbound(r_bind(p, here, benv), r_local(bte, p), kayak_rt::heap_cons(arg, bargs))
            }
        }
    }
}

/// A closure of a lambda into RESULT, its free values into REG1…REGn
/// first: of the word the stack code made (`r-made-word`); with a
/// `region` (an `rlambda`'s, one or none), made there, by
/// `%region-closure h fv … w` (C259). A leaf makes one only as its
/// value, in tail position, and none in a region. What it gives: for
/// each sibling not made yet, the free value and the sibling's slot.
pub fn r_lambda(g: &'static Rgen, ps: Strings, body: &'static Cx, env: Renv, te: Cenv, own: Strings, region: Cxs, tail: bool) -> Rpatches {
    if (g_leaf(g) && not((tail && null_p(region)))) {
        r_decline(g);
        nil::<&'static Rpatch>()
    } else {
        let m = r_made_word(ps, body, te, own);
        if null_p(m) {
            r_decline(g);
            nil::<&'static Rpatch>()
        } else {
            let tagcase_ = car(m);
            match *tagcase_ {
                Rmade::Rmade(w, fv) => {
                    let n = size(fv);
                    if not(null_p(region)) {
                        let tagcase_ = r_free_args(g, fv, env, 0i64);
                        match *tagcase_ {
                            Rfree::Rfree(r#as, ps2) => {
                                r_prim(g, str_lit("%region-closure"), kayak_rt::heap_cons(a_e(car(region)), onto(r#as, kayak_rt::heap_cons(a_v(l_word(w)), kayak_rt::nil()))), env, te);
                                ps2
                            }
                        }
                    } else if i64_gt(n, register_regs()) {
                        let tagcase_ = r_free_args(g, fv, env, 0i64);
                        match *tagcase_ {
                            Rfree::Rfree(r#as, ps2) => {
                                r_args(g, r#as, env, te, nil::<&'static Cx>());
                                r_ins(g, str_lit("lambda"), kayak_rt::heap_cons(o_word(w), kayak_rt::heap_cons(o_int(n), kayak_rt::nil())));
                                ps2
                            }
                        }
                    } else {
                        let patches = r_free_into_regs(g, fv, env);
                        r_ins(g, str_lit("lambda"), kayak_rt::heap_cons(o_word(w), kayak_rt::heap_cons(o_int(n), kayak_rt::nil())));
                        patches
                    }
                }
            }
        }
    }
}

pub fn r_thunk(g: &'static Rgen, body: &'static Cx, env: Renv, te: Cenv) -> () {
    r_lambda(g, nil::<Str>(), body, env, te, nil::<Str>(), nil::<&'static Cx>(), false);
    ()
}

/// The free values as a call-out's operands; a sibling not made yet as
/// `#f`, to be patched.
pub fn r_free_args(g: &'static Rgen, fv: Strings, env: Renv, j: i64) -> &'static Rfree {
    if null_p(fv) {
        rfree(nil::<&'static Rarg>(), nil::<&'static Rpatch>())
    } else {
        let tagcase_ = r_free_args(g, cdr(fv), env, i64_plus(j, 1i64));
        match *tagcase_ {
            Rfree::Rfree(r#as, ps) => {
                let l = r_where(env, car(fv));
                if null_p(l) {
                    r_decline(g);
                    rfree(r#as, ps)
                } else {
                    let tagcase_ = car(l);
                    match *tagcase_ {
                        Rloc::RlSlot(s) => {
                            rfree(kayak_rt::heap_cons(a_slot(s), r#as), ps)
                        }
                        Rloc::RlFree(i) => {
                            rfree(kayak_rt::heap_cons(a_lexical(i), r#as), ps)
                        }
                        Rloc::RlPending(s) => {
                            rfree(kayak_rt::heap_cons(a_v(l_bool(false)), r#as), kayak_rt::heap_cons(rpatch(j, s), ps))
                        }
                        Rloc::RlConst(c) => {
                            rfree(kayak_rt::heap_cons(a_v(rconst_lit(c)), r#as), ps)
                        }
                        _ => {
                            let y = tagcase_;
                            r_decline(g);
                            rfree(r#as, ps)
                        }
                    }
                }
            }
        }
    }
}

pub fn r_free_into_regs(g: &'static Rgen, fv: Strings, env: Renv) -> Rpatches {
    r_emit_all(g, par_move_items(r_reg_moves(fv, env, 0i64), nil::<&'static Ritem>()));
    r_free_regs(g, fv, env, 0i64)
}

/// Each free value into REGj+1, as `lambda` wants them (one in a
/// register moved already); a sibling not made yet as `#f`, patched.
pub fn r_free_regs(mut g: &'static Rgen, mut fv: Strings, mut env: Renv, mut j: i64) -> Rpatches {
    loop {
        if null_p(fv) {
            return nil::<&'static Rpatch>();
        } else {
            let (l, k) = (r_where(env, car(fv)), i64_plus(j, 1i64));
            if null_p(l) {
                r_decline(g);
                return nil::<&'static Rpatch>();
            } else {
                let tagcase_ = car(l);
                match *tagcase_ {
                    Rloc::RlReg(r) => {
                        (fv, j) = (cdr(fv), k);
                        continue;
                    }
                    Rloc::RlSlot(s) => {
                        r_opnn(g, str_lit("load"), k, s);
                        (fv, j) = (cdr(fv), k);
                        continue;
                    }
                    Rloc::RlFree(i) => {
                        r_lexical_into(g, i, k);
                        (fv, j) = (cdr(fv), k);
                        continue;
                    }
                    Rloc::RlPending(s) => {
                        r_const_into(g, l_bool(false), k);
                        return kayak_rt::heap_cons(rpatch(j, s), r_free_regs(g, cdr(fv), env, k));
                    }
                    Rloc::RlConst(c) => {
                        r_const_into(g, rconst_lit(c), k);
                        (fv, j) = (cdr(fv), k);
                        continue;
                    }
                    _ => {
                        let y = tagcase_;
                        r_decline(g);
                        return nil::<&'static Rpatch>();
                    }
                }
            }
        }
    }
}

/// Each closure made into its slot, a placeholder for a sibling not
/// made yet; then each placeholder patched; a join point no closure,
/// its calls jumps to its body, after the `letrec`'s.
pub fn r_letrec(g: &'static Rgen, bs: Cbinds, body: &'static Cx, env: Renv, te: Cenv, tail: bool) -> () {
    let slots = get(g_nslot(g));
    let regs = get(g_nreg(g));
    let joins = r_join_flags(bs, body, tail);
    let at = r_letrec_slots(g, joins);
    let made = r_letrec_make(g, bs, bs, at, 0i64, env, te, joins);
    let te2 = r_letrec_te(bs, joins, te);
    let places = {
        r_letrec_patch(g, made, at);
        r_join_places(g, bs, joins, te2)
    };
    let env2 = r_letrec_env(bs, at, places, env);
    r_exp(g, body, env2, te2, tail);
    r_join_bodies(g, bs, places, env2, te2, tail);
    r_restore(g, regs, slots)
}

pub fn r_letrec_slots(g: &'static Rgen, joins: List<bool>) -> List<i64> {
    if null_p(joins) {
        nil::<i64>()
    } else {
        let s = if car(joins) {
            the::<i64>(-1i64)
        } else {
            r_slot(g)
        };
        kayak_rt::heap_cons(s, r_letrec_slots(g, cdr(joins)))
    }
}

pub fn r_letrec_make(g: &'static Rgen, all: Cbinds, bs: Cbinds, at: List<i64>, i: i64, env: Renv, te: Cenv, joins: List<bool>) -> List<Rpatches> {
    if null_p(bs) {
        nil::<List<&'static Rpatch>>()
    } else if car(joins) {
        kayak_rt::heap_cons(nil::<&'static Rpatch>(), r_letrec_make(g, all, cdr(bs), at, i64_plus(i, 1i64), env, te, cdr(joins)))
    } else {
        let tagcase_ = car(bs);
        match *tagcase_ {
            Cbind::Cbind(name, x) => {
                let l = lambda_of(x);
                let p = if null_p(l) {
                    r_decline(g);
                    nil::<&'static Rpatch>()
                } else {
                    let tagcase_ = car(l);
                    match *tagcase_ {
                        Lparts::Lparts(ps, lbody, region) => {
                            let tagcase_ = r_sibling_env(all, at, i, 0i64, lbody, size(ps), env, te);
                            match *tagcase_ {
                                Rscope::Rscope(e2, te2) => {
                                    r_lambda(g, ps, lbody, e2, te2, kayak_rt::heap_cons(name, kayak_rt::nil()), region, false)
                                }
                            }
                        }
                    }
                };
                r_opn(g, str_lit("setstk"), r_nth_int(at, i));
                kayak_rt::heap_cons(p, r_letrec_make(g, all, cdr(bs), at, i64_plus(i, 1i64), env, te, cdr(joins)))
            }
        }
    }
}

/// Each sibling where the closure being made sees it: a loop, if it is
/// this one and only called so in its body; else the slot it will be
/// in, not made yet.
pub fn r_sibling_env(mut bs: Cbinds, mut at: List<i64>, mut i: i64, mut k: i64, mut lbody: &'static Cx, mut n: i64, mut env: Renv, mut te: Cenv) -> &'static Rscope {
    loop {
        if null_p(bs) {
            return rscope(env, te);
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Cbind::Cbind(sib, x) => {
                    let (loops, s) = ((i64_eq(k, i) && c_loops_only(lbody, sib, n, true)), r_nth_int(at, k));
                    (bs, k, env, te) = (cdr(bs), i64_plus(k, 1i64), r_bind(sib, if loops {
                        rl_loop()
                    } else {
                        rl_pending(s)
                    }, env), c_extend(sib, if loops {
                        at_loop()
                    } else {
                        at_pending(s)
                    }, te));
                    continue;
                }
            }
        }
    }
}

pub fn r_letrec_patch(mut g: &'static Rgen, mut made: List<Rpatches>, mut at: List<i64>) -> () {
    loop {
        if null_p(made) {
            return ();
        } else {
            r_patch_one(g, car(made), car(at));
            (made, at) = (cdr(made), cdr(at));
            continue;
        }
    }
}

pub fn r_patch_one(mut g: &'static Rgen, mut ps: Rpatches, mut slot: i64) -> () {
    loop {
        if null_p(ps) {
            return ();
        } else {
            let tagcase_ = car(ps);
            match *tagcase_ {
                Rpatch::Rpatch(j, s) => {
                    r_opnn(g, str_lit("load"), 1i64, s);
                    r_opn(g, str_lit("stack"), slot);
                    r_opnn(g, str_lit("setfield"), i64_plus(3i64, j), 1i64);
                    ps = cdr(ps);
                    continue;
                }
            }
        }
    }
}

/// Each join point's place: its parameters' places, registers where its
/// body calls nothing (or in a leaf), so many as leave half of them,
/// else frame slots; and its label. None for one that is not.
pub fn r_join_places(g: &'static Rgen, bs: Cbinds, joins: List<bool>, named: Cenv) -> List<List<&'static Rplace>> {
    if null_p(bs) {
        nil::<List<&'static Rplace>>()
    } else {
        let here = the::<List<&'static Rplace>>(if car(joins) {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Cbind::Cbind(n, x) => {
                    let tagcase_ = car(lambda_of(x));
                    match *tagcase_ {
                        Lparts::Lparts(ps, lbody, region) => {
                            let regs = (g_leaf(g) || (not(r_collects(g_view(g), lbody, r_locals(ps, named), g_this(g), true)) && i64_lt_eq(i64_plus(get(g_nreg(g)), size(ps)), r_half_regs())));
                            let locs = r_param_places(g, ps, regs);
                            let label = r_new_label(g);
                            the::<List<&'static Rplace>>(kayak_rt::heap_cons(rplace(locs, label), kayak_rt::nil()))
                        }
                    }
                }
            }
        } else {
            nil::<&'static Rplace>()
        });
        kayak_rt::heap_cons(here, r_join_places(g, cdr(bs), cdr(joins), named))
    }
}

pub fn r_param_places(g: &'static Rgen, ps: Strings, regs: bool) -> Rlocs {
    if null_p(ps) {
        nil::<&'static Rloc>()
    } else {
        let l = if regs {
            rl_reg(r_reg(g))
        } else {
            rl_slot(r_slot(g))
        };
        kayak_rt::heap_cons(l, r_param_places(g, cdr(ps), regs))
    }
}

/// Each join point's body, after the `letrec`'s, which ends every path
/// itself: where its calls go.
pub fn r_join_bodies(mut g: &'static Rgen, mut bs: Cbinds, mut places: List<List<&'static Rplace>>, mut env: Renv, mut te: Cenv, mut tail: bool) -> () {
    loop {
        if null_p(bs) {
            return ();
        } else {
            if null_p(car(places)) {
                ()
            } else {
                let tagcase_ = car(bs);
                match *tagcase_ {
                    Cbind::Cbind(n, x) => {
                        let tagcase_ = car(lambda_of(x));
                        match *tagcase_ {
                            Lparts::Lparts(ps, lbody, region) => {
                                let tagcase_ = car(car(places));
                                match *tagcase_ {
                                    Rplace::Rplace(locs, label) => {
                                        r_emit(g, ri_label(label));
                                        r_exp(g, lbody, r_bind_places(env, ps, locs), r_locals(ps, te), tail)
                                    }
                                }
                            }
                        }
                    }
                }
            };
            (bs, places) = (cdr(bs), cdr(places));
            continue;
        }
    }
}

/// A join point's call: each argument made and kept (a register where no
/// later argument calls), then each into its parameter's place, and a
/// jump.
pub fn r_jump(g: &'static Rgen, j: &'static Rloc, args: Cxs, env: Renv, te: Cenv, tail: bool) -> () {
    let tagcase_ = j;
    match *tagcase_ {
        Rloc::RlJoin(params, label) => {
            if (not(tail) || not(i64_eq(size(args), size(params)))) {
                r_decline(g)
            } else {
                let regs = get(g_nreg(g));
                let slots = get(g_nslot(g));
                let made = r_jump_args(g, args, env, te, r_in_regs(g, args, 0i64, te, false));
                r_jump_moves(g, made, params);
                r_emit(g, ri_branch(str_lit("branch"), label));
                r_restore(g, regs, slots)
            }
        }
        _ => {
            let y = tagcase_;
            r_decline(g)
        }
    }
}

pub fn r_jump_args(g: &'static Rgen, args: Cxs, env: Renv, te: Cenv, flags: List<bool>) -> Rlocs {
    if null_p(args) {
        nil::<&'static Rloc>()
    } else {
        let l = {
            r_exp(g, car(args), env, te, false);
            r_keep(g, car(flags))
        };
        kayak_rt::heap_cons(l, r_jump_args(g, cdr(args), env, te, cdr(flags)))
    }
}

pub fn r_jump_moves(mut g: &'static Rgen, mut made: Rlocs, mut params: Rlocs) -> () {
    loop {
        if (null_p(made) || null_p(params)) {
            return ();
        } else {
            {
                let tagcase_ = car(made);
                match *tagcase_ {
                    Rloc::RlReg(a) => {
                        let tagcase_ = car(params);
                        match *tagcase_ {
                            Rloc::RlReg(b) => {
                                r_opnn(g, str_lit("movereg"), a, b)
                            }
                            Rloc::RlSlot(b) => {
                                r_opn(g, str_lit("reg"), a);
                                r_opn(g, str_lit("setstk"), b)
                            }
                            _ => {
                                let y = tagcase_;
                                r_decline(g)
                            }
                        }
                    }
                    Rloc::RlSlot(a) => {
                        let tagcase_ = car(params);
                        match *tagcase_ {
                            Rloc::RlReg(b) => {
                                r_opnn(g, str_lit("load"), b, a)
                            }
                            Rloc::RlSlot(b) => {
                                r_slot_move(g, a, b)
                            }
                            _ => {
                                let y = tagcase_;
                                r_decline(g)
                            }
                        }
                    }
                    _ => {
                        let y = tagcase_;
                        r_decline(g)
                    }
                }
            };
            (made, params) = (cdr(made), cdr(params));
            continue;
        }
    }
}

/// The scrutinee kept; each arm's tag compared, the last's not when
/// there is no `else` (a checked program covers every tag); the value,
/// or its product's members, bound.
pub fn r_tagcase(g: &'static Rgen, s: &'static Cx, arms: List<&'static Carm>, els: Cbinds, env: Renv, te: Cenv, tail: bool) -> () {
    let (regs, slots) = (get(g_nreg(g)), get(g_nslot(g)));
    r_exp(g, s, env, te, false);
    {
        let sc = r_place_value(g);
        let end = r_new_label(g);
        r_arms(g, arms, null_p(els), sc, end, env, te, tail);
        if null_p(els) {
            ()
        } else {
            let tagcase_ = car(els);
            match *tagcase_ {
                Cbind::Cbind(n, x) => {
                    r_exp(g, x, r_bind(n, sc, env), r_local(te, n), tail)
                }
            }
        };
        r_emit(g, ri_label(end))
    };
    r_restore(g, regs, slots)
}

pub fn r_arms(mut g: &'static Rgen, mut arms: List<&'static Carm>, mut no_else: bool, mut sc: &'static Rloc, mut end: i64, mut env: Renv, mut te: Cenv, mut tail: bool) -> () {
    loop {
        if null_p(arms) {
            return ();
        } else {
            let tagcase_ = car(arms);
            match *tagcase_ {
                Carm::Carm(tag, whole, ns, body) => {
                    let last = (no_else && null_p(cdr(arms)));
                    let next = r_new_label(g);
                    let regs = get(g_nreg(g));
                    let slots = get(g_nslot(g));
                    if last {
                        ()
                    } else {
                        r_get(g, sc);
                        r_opn(g, str_lit("field"), 2i64);
                        r_op2imm(g, str_lit("eq"), l_sym(tag));
                        r_emit(g, ri_branch(str_lit("branchf"), next))
                    };
                    {
                        let bound = if whole {
                            r_members(g, sc, ns, 0i64, body, nil::<&'static Rbind>())
                        } else {
                            r_get(g, sc);
                            r_opn(g, str_lit("field"), 3i64);
                            r_bind(car(ns), r_place_value(g), nil::<&'static Rbind>())
                        };
                        let in_order = the::<Renv>(reverse(bound));
                        r_exp(g, body, r_bind_all(in_order, env), r_local_all(in_order, te), tail)
                    };
                    r_restore(g, regs, slots);
                    if tail {
                        ()
                    } else {
                        r_emit(g, ri_branch(str_lit("branch"), end))
                    };
                    r_emit(g, ri_label(next));
                    arms = cdr(arms);
                    continue;
                }
            }
        }
    }
}

/// A product's members the arm's body uses, each kept, newest first.
pub fn r_members(mut g: &'static Rgen, mut sc: &'static Rloc, mut xs: Strings, mut j: i64, mut body: &'static Cx, mut acc: Renv) -> Renv {
    loop {
        if null_p(xs) {
            return acc;
        } else if not(c_mentions_p(body, car(xs))) {
            (xs, j) = (cdr(xs), i64_plus(j, 1i64));
            continue;
        } else {
            r_get(g, sc);
            r_opn(g, str_lit("field"), 3i64);
            r_opn(g, str_lit("field"), i64_plus(j, 2i64));
            let l = r_place_value(g);
            (xs, j, acc) = (cdr(xs), i64_plus(j, 1i64), r_bind(car(xs), l, acc));
            continue;
        }
    }
}

/// `(apply f xs)`: `f` a `vsubr`, a closure over the procedure of one
/// list, free value 0; that procedure called with `xs`, as the stack
/// code calls it (no copy).
pub fn r_apply(g: &'static Rgen, args: Cxs, env: Renv, te: Cenv, tail: bool) -> () {
    if g_leaf(g) {
        r_decline(g)
    } else {
        let (regs, slots) = (get(g_nreg(g)), get(g_nslot(g)));
        r_args(g, r_exp_args(args), env, te, nil::<&'static Cx>());
        {
            let s = r_slot(g);
            r_opn(g, str_lit("reg"), 1i64);
            r_opn(g, str_lit("field"), 3i64);
            r_opn(g, str_lit("setstk"), s);
            r_opn(g, str_lit("reg"), 2i64);
            r_opn(g, str_lit("setreg"), 1i64);
            r_opn(g, str_lit("stack"), s);
            r_invoke(g, 1i64, tail, 0i64)
        };
        r_restore(g, regs, slots)
    }
}

/// `(list x …)`: every argument not simple, or in a register, made and
/// kept first, in order; then the pairs made from the last, onto `nil`.
pub fn r_list(g: &'static Rgen, args: Cxs, env: Renv, te: Cenv) -> () {
    if g_leaf(g) {
        r_decline(g)
    } else {
        let slots = get(g_nslot(g));
        let r#as = r_exp_args(args);
        let kept = r_args_hard(g, r#as, 0i64, -1i64, env, te, true);
        r_const(g, l_nil());
        r_args_list(g, r#as, kept, i64_minus(size(r#as), 1i64), 0i64, env, te);
        set(g_nslot(g), slots)
    }
}

/// The arguments into REG1…REGn, in order, then `f`, if a call's, into
/// RESULT. An argument that is not simple is kept in the frame until all
/// are made; a simple one is made last. Past `register-regs`, REG8 a
/// list of the rest, made by `cons`, which may collect.
pub fn r_args(g: &'static Rgen, args: Rargs, env: Renv, te: Cenv, f: Cxs) -> () {
    if g_leaf(g) {
        r_decline(g)
    } else {
        let n = size(args);
        let many = i64_gt(n, register_regs());
        let slots = get(g_nslot(g));
        let hard_f = (not(null_p(f)) && not(r_simple_p(car(f))));
        let direct = if (many || hard_f) {
            the::<i64>(-1i64)
        } else {
            r_last_hard(args, 0i64, -1i64)
        };
        let kept = r_args_hard(g, args, 0i64, direct, env, te, many);
        let fun = if hard_f {
            r_exp(g, car(f), env, te, false);
            r_keep_in_slot(g)
        } else {
            the::<i64>(-1i64)
        };
        if many {
            r_const(g, l_nil());
            r_args_list(g, args, kept, i64_minus(n, 1i64), i64_minus(register_regs(), 1i64), env, te);
            let s = r_slot(g);
            r_opn(g, str_lit("setstk"), s);
            r_args_into(g, args, kept, 0i64, i64_minus(register_regs(), 1i64), env, te);
            r_opnn(g, str_lit("load"), register_regs(), s)
        } else {
            r_args_into(g, args, kept, 0i64, n, env, te)
        };
        if i64_gt_eq(fun, 0i64) {
            r_opn(g, str_lit("stack"), fun)
        } else if not(null_p(f)) {
            r_exp(g, car(f), env, te, false)
        } else {
            ()
        };
        set(g_nslot(g), slots)
    }
}

/// Each argument: -1 if simple, made later; -2 if made into its
/// register now; else the frame slot it is kept in.
pub fn r_args_hard(g: &'static Rgen, args: Rargs, i: i64, direct: i64, env: Renv, te: Cenv, many: bool) -> List<i64> {
    if null_p(args) {
        nil::<i64>()
    } else {
        if r_arg_simple_here_p(car(args), env, many) {
            kayak_rt::heap_cons(the::<i64>(-1i64), r_args_hard(g, cdr(args), i64_plus(i, 1i64), direct, env, te, many))
        } else {
            {
                let tagcase_ = car(args);
                match *tagcase_ {
                    Rarg::AE(x) => {
                        r_exp(g, x, env, te, false)
                    }
                    Rarg::AThunk(b) => {
                        r_thunk(g, b, env, te)
                    }
                    _ => {
                        let y = tagcase_;
                        ()
                    }
                }
            };
            let k = if i64_eq(i, direct) {
                r_opn(g, str_lit("setreg"), i64_plus(i, 1i64));
                the::<i64>(-2i64)
            } else {
                r_keep_in_slot(g)
            };
            kayak_rt::heap_cons(k, r_args_hard(g, cdr(args), i64_plus(i, 1i64), direct, env, te, many))
        }
    }
}

pub fn r_args_into(mut g: &'static Rgen, mut args: Rargs, mut kept: List<i64>, mut i: i64, mut stop: i64, mut env: Renv, mut te: Cenv) -> () {
    loop {
        if (null_p(args) || i64_eq(i, stop)) {
            return ();
        } else {
            r_arg_into(g, car(args), car(kept), i64_plus(i, 1i64), env, te);
            (args, kept, i) = (cdr(args), cdr(kept), i64_plus(i, 1i64));
            continue;
        }
    }
}

pub fn r_arg_into(g: &'static Rgen, a: &'static Rarg, kept: i64, k: i64, env: Renv, te: Cenv) -> () {
    if i64_eq(kept, -2i64) {
        ()
    } else if i64_gt_eq(kept, 0i64) {
        r_opnn(g, str_lit("load"), k, kept)
    } else {
        let tagcase_ = a;
        match *tagcase_ {
            Rarg::AE(x) => {
                r_into(g, x, k, env, te)
            }
            Rarg::AV(v) => {
                r_const_into(g, v, k)
            }
            Rarg::ASlot(s) => {
                r_opnn(g, str_lit("load"), k, s)
            }
            Rarg::ALexical(j) => {
                r_lexical_into(g, j, k)
            }
            Rarg::AThunk(b) => {
                ()
            }
        }
    }
}

/// The arguments from the `i`th down to the `from`th, onto the list in
/// RESULT, by `cons`.
pub fn r_args_list(mut g: &'static Rgen, mut args: Rargs, mut kept: List<i64>, mut i: i64, mut from: i64, mut env: Renv, mut te: Cenv) -> () {
    loop {
        if i64_lt(i, from) {
            return ();
        } else {
            r_opn(g, str_lit("setreg"), 2i64);
            r_arg_into(g, r_nth_arg(args, i), r_nth_int(kept, i), 1i64, env, te);
            r_ins(g, str_lit("cellular"), kayak_rt::heap_cons(o_prim(str_lit("cons")), kayak_rt::heap_cons(o_int(2i64), kayak_rt::nil())));
            i = i64_minus(i, 1i64);
            continue;
        }
    }
}

pub fn r_call_out(g: &'static Rgen, how: Str, what: Str, args: Rargs, env: Renv, te: Cenv) -> () {
    r_args(g, args, env, te, nil::<&'static Cx>());
    r_ins(g, how, kayak_rt::heap_cons(o_prim(what), kayak_rt::heap_cons(o_int(size(args)), kayak_rt::nil())))
}

/// Runtime primitive `name`: in line if it never collects and its
/// operands are a value and a constant (`prim2imm`), or a value
/// (`prim1`); else a call-out.
pub fn r_prim(g: &'static Rgen, name: Str, args: Rargs, env: Renv, te: Cenv) -> () {
    let n = size(args);
    if (r_never_collects_p(name) && i64_eq(n, 1i64) && r_arg_loaded(g, car(args), env, te)) {
        r_ins(g, str_lit("prim1"), kayak_rt::heap_cons(o_prim(name), kayak_rt::nil()))
    } else if (r_never_collects_p(name) && i64_eq(n, 2i64) && {
        let tagcase_ = car(cdr(args));
        match *tagcase_ {
            Rarg::AV(v) => {
                true
            }
            _ => {
                let y = tagcase_;
                false
            }
        }
    } && r_arg_loaded(g, car(args), env, te)) {
        r_ins(g, str_lit("prim2imm"), kayak_rt::heap_cons(o_prim(name), kayak_rt::heap_cons({
            let tagcase_ = car(cdr(args));
            match *tagcase_ {
                Rarg::AV(v) => {
                    o_lit(v)
                }
                _ => {
                    let y = tagcase_;
                    o_int(0i64)
                }
            }
        }, kayak_rt::nil())))
    } else {
        r_call_out(g, str_lit("prim"), name, args, env, te)
    }
}

pub fn r_arg_loaded(g: &'static Rgen, a: &'static Rarg, env: Renv, te: Cenv) -> bool {
    let tagcase_ = a;
    match *tagcase_ {
        Rarg::AE(x) => {
            r_exp(g, x, env, te, false);
            true
        }
        Rarg::ASlot(s) => {
            r_opn(g, str_lit("stack"), s);
            true
        }
        _ => {
            let y = tagcase_;
            false
        }
    }
}

/// Arrays, and the tag and key makers: as the stack compiler does them.
pub fn r_special(g: &'static Rgen, what: Str, args: Cxs, env: Renv, te: Cenv) -> () {
    if string_eq_p(what, str_lit("array-ref")) {
        r_args(g, r_exp_args(args), env, te, nil::<&'static Cx>());
        r_index_field(g);
        r_ins(g, str_lit("cellular"), kayak_rt::heap_cons(o_prim(str_lit("field@")), kayak_rt::heap_cons(o_int(2i64), kayak_rt::nil())))
    } else if string_eq_p(what, str_lit("array-set!")) {
        r_args(g, r_exp_args(args), env, te, nil::<&'static Cx>());
        r_index_field(g);
        r_ins(g, str_lit("prim"), kayak_rt::heap_cons(o_prim(str_lit("%bloblet-set!")), kayak_rt::heap_cons(o_int(3i64), kayak_rt::nil())));
        r_unit(g)
    } else if string_eq_p(what, str_lit("array-length")) {
        r_prim(g, str_lit("%bloblet-fields"), r_exp_args(args), env, te);
        r_add_imm(g, int_lit(-1))
    } else if string_eq_p(what, str_lit("make-array")) {
        r_prim(g, str_lit("%make-bloblet-filled"), kayak_rt::heap_cons(a_v(l_int(int_lit(0))), kayak_rt::heap_cons(a_e(car(args)), kayak_rt::heap_cons(a_e(car(cdr(args))), kayak_rt::nil()))), env, te)
    } else if string_eq_p(what, str_lit("make-box")) {
        r_prim(g, str_lit("%make-box"), kayak_rt::heap_cons(a_v(l_unit()), kayak_rt::nil()), env, te)
    } else if (string_eq_p(what, str_lit("set-car!")) || string_eq_p(what, str_lit("set-cdr!"))) {
        r_prim(g, what, r_exp_args(args), env, te);
        r_unit(g)
    } else {
        r_decline(g)
    }
}

pub fn r_index_field(g: &'static Rgen) -> () {
    r_opn(g, str_lit("reg"), 2i64);
    r_add_imm(g, int_lit(2));
    r_opn(g, str_lit("setreg"), 2i64)
}

/// RESULT := r(a, b), `a` evaluated first; a constant `b` an immediate.
pub fn r_binary(g: &'static Rgen, r: Str, a: &'static Cx, b: &'static Cx, env: Renv, te: Cenv) -> () {
    let tagcase_ = r_operands(g, a, b, env, te, true);
    match *tagcase_ {
        Roperands::RopImm(v) => {
            r_op2imm(g, r, v)
        }
        Roperands::RopReg(k) => {
            r_ins(g, str_lit("op2"), kayak_rt::heap_cons(o_prim(r), kayak_rt::heap_cons(o_int(k), kayak_rt::nil())))
        }
        Roperands::RopNone() => {
            r_decline(g)
        }
    }
}

pub fn r_pure2(g: &'static Rgen, p: Str, a: &'static Cx, b: &'static Cx, env: Renv, te: Cenv) -> () {
    let tagcase_ = r_operands(g, a, b, env, te, true);
    match *tagcase_ {
        Roperands::RopImm(v) => {
            r_ins(g, str_lit("prim2imm"), kayak_rt::heap_cons(o_prim(p), kayak_rt::heap_cons(o_lit(v), kayak_rt::nil())))
        }
        Roperands::RopReg(k) => {
            r_ins(g, str_lit("prim2"), kayak_rt::heap_cons(o_prim(p), kayak_rt::heap_cons(o_int(k), kayak_rt::nil())))
        }
        Roperands::RopNone() => {
            r_decline(g)
        }
    }
}

/// RESULT := r(y, x), `x` evaluated first, as written; `x` kept in a
/// register, or the frame if `y` calls.
pub fn r_binary_swapped(g: &'static Rgen, r: Str, x: &'static Cx, y: &'static Cx, env: Renv, te: Cenv) -> () {
    let (regs, slots) = (get(g_nreg(g)), get(g_nslot(g)));
    r_exp(g, x, env, te, false);
    {
        let collects = r_collects_here_p(g, y, te, false);
        let k = r_reg(g);
        if collects {
            let s = r_slot(g);
            r_opn(g, str_lit("setstk"), s);
            r_exp(g, y, env, te, false);
            r_opnn(g, str_lit("load"), k, s)
        } else {
            r_opn(g, str_lit("setreg"), k);
            r_exp(g, y, env, te, false)
        };
        r_ins(g, str_lit("op2"), kayak_rt::heap_cons(o_prim(r), kayak_rt::heap_cons(o_int(k), kayak_rt::nil())))
    };
    r_restore(g, regs, slots)
}

/// `a` into RESULT and `b` into a register, `a` evaluated first; or, if
/// `imm` and `b` is a constant, `b` as an immediate. The register is
/// free again after: use it at once.
pub fn r_operands(g: &'static Rgen, a: &'static Cx, b: &'static Cx, env: Renv, te: Cenv, imm: bool) -> &'static Roperands {
    let regs = get(g_nreg(g));
    let slots = get(g_nslot(g));
    let v = if imm {
        r_known_cell(env, b)
    } else {
        nil::<&'static Lit>()
    };
    let breg = r_reg_of(r_var_loc(env, b));
    let out = if not(null_p(v)) {
        r_exp(g, a, env, te, false);
        rop_imm(car(v))
    } else if i64_gt(breg, 0i64) {
        r_exp(g, a, env, te, false);
        rop_reg(breg)
    } else if r_simple_p(a) {
        let k = if r_simple_p(b) {
            let k = r_reg(g);
            r_into(g, b, k, env, te);
            k
        } else {
            r_exp(g, b, env, te, false);
            r_keep_in_reg(g)
        };
        r_exp(g, a, env, te, false);
        rop_reg(k)
    } else {
        r_exp(g, a, env, te, false);
        let kept = r_keep(g, not(r_collects_here_p(g, b, te, false)));
        let k = r_reg(g);
        r_into(g, b, k, env, te);
        r_get(g, kept);
        rop_reg(k)
    };
    r_restore(g, regs, slots);
    out
}

/// `x`'s value into REGk: straight from a register or the frame when it
/// is a variable there, else by way of RESULT.
pub fn r_into(g: &'static Rgen, x: &'static Cx, k: i64, env: Renv, te: Cenv) -> () {
    let l = r_plain_var_loc(env, x);
    if null_p(l) {
        r_exp(g, x, env, te, false);
        r_opn(g, str_lit("setreg"), k)
    } else {
        let tagcase_ = car(l);
        match *tagcase_ {
            Rloc::RlSlot(s) => {
                r_opnn(g, str_lit("load"), k, s)
            }
            Rloc::RlReg(r) => {
                if i64_eq(r, k) {
                    ()
                } else {
                    r_opnn(g, str_lit("movereg"), r, k)
                }
            }
            _ => {
                let y = tagcase_;
                r_exp(g, x, env, te, false);
                r_opn(g, str_lit("setreg"), k)
            }
        }
    }
}

/// A tail call of the procedure itself: the new arguments made, then put
/// where the parameters are, and back to the start.
pub fn r_loop(g: &'static Rgen, args: Cxs, env: Renv, te: Cenv) -> () {
    let regs = get(g_nreg(g));
    let slots = get(g_nslot(g));
    let made = r_loop_make(g, args, env, te);
    r_loop_move(g, made, 0i64);
    r_emit(g, ri_branch(str_lit("branch"), g_start(g)));
    r_restore(g, regs, slots)
}

pub fn r_loop_make(g: &'static Rgen, args: Cxs, env: Renv, te: Cenv) -> List<i64> {
    if null_p(args) {
        nil::<i64>()
    } else {
        r_exp(g, car(args), env, te, false);
        let m = if g_leaf(g) {
            r_keep_in_reg(g)
        } else {
            r_keep_in_slot(g)
        };
        kayak_rt::heap_cons(m, r_loop_make(g, cdr(args), env, te))
    }
}

pub fn r_loop_move(mut g: &'static Rgen, mut made: List<i64>, mut i: i64) -> () {
    loop {
        if null_p(made) {
            return ();
        } else {
            if g_leaf(g) {
                r_opnn(g, str_lit("movereg"), car(made), i64_plus(i, 1i64))
            } else {
                r_slot_move(g, car(made), i)
            };
            (made, i) = (cdr(made), i64_plus(i, 1i64));
            continue;
        }
    }
}

/// A procedure calling itself through its global `cell`: the arguments
/// made; then, if the global has not been written since, this
/// procedure again, by its own entry, or in tail position a loop back
/// to `start`; else the global's.
pub fn r_self_guarded(g: &'static Rgen, cell: Str, start: i64, f: &'static Cx, args: Cxs, a: i64, env: Renv, te: Cenv, tail: bool) -> () {
    let (n, conv) = (size(args), r_conv_at(a));
    if (g_leaf(g) && (not((tail && x_assuming(g_ctx(g)))) || i64_gt(n, register_regs()))) {
        r_decline(g)
    } else {
        let (regs, slots, call, end) = (get(g_nreg(g)), get(g_nslot(g)), r_new_label(g), r_new_label(g));
        if tail {
            let made = r_self_temps(g, args, 0i64, env, te);
            let assumed = r_assume(g, cell);
            if assumed {
                ()
            } else {
                r_guard(g, cell, call)
            };
            r_self_moves(g, made, 0i64);
            r_emit(g, ri_branch(str_lit("branch"), start));
            if assumed {
                set(x_looped(g_ctx(g)), true)
            } else {
                r_emit(g, ri_label(call));
                r_args(g, r_slot_args_of(g, made), env, te, kayak_rt::heap_cons(f, kayak_rt::nil()));
                r_invoke(g, n, true, conv)
            }
        } else {
            r_args(g, r_exp_args(args), env, te, nil::<&'static Cx>());
            if r_assume(g, cell) {
                r_opn(g, str_lit("invokeself"), n)
            } else {
                r_guard(g, cell, call);
                r_opn(g, str_lit("invokeself"), n);
                r_emit(g, ri_branch(str_lit("branch"), end));
                r_emit(g, ri_label(call));
                r_ins(g, str_lit("global"), kayak_rt::heap_cons(o_global(cell), kayak_rt::nil()));
                r_opnn(g, str_lit("invoke"), n, conv);
                r_emit(g, ri_label(end))
            }
        };
        r_restore(g, regs, slots)
    }
}

pub fn r_self_temps(g: &'static Rgen, args: Cxs, i: i64, env: Renv, te: Cenv) -> Rlocs {
    if null_p(args) {
        nil::<&'static Rloc>()
    } else {
        let l = r_self_temp(g, car(args), i, env, te);
        kayak_rt::heap_cons(l, r_self_temps(g, cdr(args), i64_plus(i, 1i64), env, te))
    }
}

/// Argument `i` of a loop kept: where it is already if it is the
/// parameter itself, unchanged; else as `r-place-value` keeps it.
pub fn r_self_temp(g: &'static Rgen, x: &'static Cx, i: i64, env: Renv, te: Cenv) -> &'static Rloc {
    let (v, leaf) = (r_plain_var_loc(env, x), g_leaf(g));
    if (not(null_p(v)) && {
        let tagcase_ = car(v);
        match *tagcase_ {
            Rloc::RlReg(r) => {
                (leaf && i64_eq(r, i64_plus(i, 1i64)))
            }
            Rloc::RlSlot(n) => {
                (not(leaf) && i64_eq(n, i))
            }
            _ => {
                let y = tagcase_;
                false
            }
        }
    }) {
        car(v)
    } else {
        r_exp(g, x, env, te, false);
        r_place_value(g)
    }
}

/// A call in tail position in a leaf, which has no frame: the arguments
/// sorted; the procedure into RESULT now if nothing after the moves
/// uses RESULT, else kept in a register; the moves; the simple
/// arguments; the call. Its own registers above REG1…REGn.
pub fn r_leaf_tail_call(g: &'static Rgen, f: &'static Cx, args: Cxs, a: i64, env: Renv, te: Cenv) -> () {
    let regs = get(g_nreg(g));
    let above = set(g_nreg(g), if i64_gt(regs, size(args)) {
        regs
    } else {
        size(args)
    });
    let made = r_leaf_args(g, args, env, te, 1i64);
    let tagcase_ = made;
    match *tagcase_ {
        Rleaf::Rleaf(ms, late) => {
            let quiet = (null_p(late) && not(moves_cycle_p(ms)));
            let fr = r_reg_of(r_plain_var_loc(env, f));
            let written = (i64_gt(fr, 0i64) && r_written_p(fr, ms, late));
            let at = if (i64_gt(fr, 0i64) && not(written)) {
                fr
            } else if (written && quiet) {
                r_opn(g, str_lit("reg"), fr);
                the::<i64>(-1i64)
            } else if written {
                r_reg(g)
            } else if r_simple_p(f) {
                the::<i64>(0i64)
            } else {
                r_exp(g, f, env, te, false);
                if quiet {
                    the::<i64>(-1i64)
                } else {
                    r_keep_in_reg(g)
                }
            };
            let moves = if (written && not(quiet)) {
                moves_snoc(ms, fr, at)
            } else {
                ms
            };
            r_emit_all(g, par_move_items(moves, nil::<&'static Ritem>()));
            r_late_into(g, late, env, te);
            if i64_gt(at, 0i64) {
                r_opn(g, str_lit("reg"), at)
            } else if i64_eq(at, 0i64) {
                r_exp(g, f, env, te, false)
            } else {
                ()
            };
            r_opnn(g, str_lit("tailinvoke"), size(args), r_conv_at(a));
            set(g_nreg(g), regs)
        }
    }
}

pub fn r_leaf_args(g: &'static Rgen, args: Cxs, env: Renv, te: Cenv, k: i64) -> &'static Rleaf {
    if null_p(args) {
        rleaf(nil::<&'static Rmove>(), nil::<&'static Rlate>())
    } else {
        let a = car(args);
        let r = r_reg_of(r_plain_var_loc(env, a));
        if i64_gt(r, 0i64) {
            let rest = r_leaf_args(g, cdr(args), env, te, i64_plus(k, 1i64));
            if i64_eq(r, k) {
                rest
            } else {
                let tagcase_ = rest;
                match *tagcase_ {
                    Rleaf::Rleaf(ms, late) => {
                        rleaf(kayak_rt::heap_cons(rmove(r, k), ms), late)
                    }
                }
            }
        } else if r_simple_p(a) {
            let tagcase_ = r_leaf_args(g, cdr(args), env, te, i64_plus(k, 1i64));
            match *tagcase_ {
                Rleaf::Rleaf(ms, late) => {
                    rleaf(ms, kayak_rt::heap_cons(rlate(k, a), late))
                }
            }
        } else {
            let t = {
                r_exp(g, a, env, te, false);
                r_keep_in_reg(g)
            };
            let tagcase_ = r_leaf_args(g, cdr(args), env, te, i64_plus(k, 1i64));
            match *tagcase_ {
                Rleaf::Rleaf(ms, late) => {
                    rleaf(kayak_rt::heap_cons(rmove(t, k), ms), late)
                }
            }
        }
    }
}

pub fn r_late_into(mut g: &'static Rgen, mut late: List<&'static Rlate>, mut env: Renv, mut te: Cenv) -> () {
    loop {
        if null_p(late) {
            return ();
        } else {
            let tagcase_ = car(late);
            match *tagcase_ {
                Rlate::Rlate(k, x) => {
                    r_into(g, x, k, env, te);
                    late = cdr(late);
                    continue;
                }
            }
        }
    }
}

